window.LING285_MODULE3 = {"moduleId": "module3", "title": "Module III", "study": {"title": "Study this first · Module III", "lead": "If you study only one page of Module III, study this one. It covers the LLM part of the course in order. Lectures 17 and 18 come first, because he said the LLM part is kept for the final. Lecture 19, the first lecture after Exam 2, comes next. Each topic has what to know, the slide beside the notes, and questions with their answers.", "askLead": "Questions on Lectures 17 to 19 in the way he asks them, with answers. His own Lab 9 questions are marked. The questions marked Predicted are written from the slides. They are predictions, not confirmed exam questions.", "focusLabel": "Module III focus (predicted questions, with answers)"}, "versions": {"module3-v1": {"label": "Module III · Study this first (Lectures 17–19, notes with the slides beside them)", "range": "Lectures 17 to 19", "split": true, "notes": true, "howToAnswer": [], "scope": {"label": "On the final", "covers": "Module III is the LLM part of the course. It holds Lectures 17 and 18, which also stay in Module II, and Lecture 19 from November 17, the first lecture after Exam 2. The final exam is cumulative, so Modules I and II come back too.", "final": "", "evidence": "On November 10 he said the review and homework questions go up to right before LLMs, and that the LLM part is kept for the final. That part is Lectures 17 and 18. Lecture 19 repeats seven Lecture 18 slides and then adds eleven new slides on training an LLM with words, sounds and images. No review sheet for the final has been handed out yet, and there is no class transcript for November 17. Every question on the new slides is marked Predicted. They are predictions, not confirmed exam questions."}, "flags": ["The notes for Lectures 17 and 18 are the same notes as on the Module II study page, shown here again and not rewritten.", "The notes for the new Lecture 19 slides come from the slides and their speaker notes only. There is no class transcript for November 17, so anything he added out loud is not here.", "The speech in the three cute puppies example was made with a speech synthesizer (an MBROLA diphone voice). It is not a recording of a person.", "The slides call the visual input the picture. These notes say image and image patch.", "The last slide lists a schedule that protects what was already learned, and it does not explain the schedule. These notes repeat the item and add nothing from outside the slides."], "topics": [{"id": "m3-lead-up", "tier": "Kept for the final", "lectures": "Lecture 17 (start) and Lecture 18", "title": "Leading up to LLMs: from one neuron to networks that unfold over time", "note": "", "blocks": [{"main": "**A neuron in an artificial neural network takes in a vector (a list of numbers) and gives back one number.** It multiplies each input by its weight and adds the results. This is called the **inner product**. A **neural network** repeats the inner product layer after layer.", "sub": ["A neural network takes in one vector and gives back a vector of decisions."], "ref": "Lecture 17 · p2", "media": {"image": "assets/slides/lecture17/002.webp", "caption": "Lecture 17 · p2"}}, {"main": "**Artificial neural networks began in biology, not in technology.** The first paper on artificial neural networks was by **McCulloch and Pitts**. It started from the all-or-none behavior of real neurons. A real neuron is either firing or not firing. This is the same idea as the **sigmoid** (a function that turns a number into a value between 0 and 1).", "sub": ["The earliest neural network work tried to model how the mind works, including mental illness.", "In the **Parallel Distributed Processing** books, **parallel** means many neurons calculate their activations at the same time.", "**Distributed** means the information from the inputs is spread across all the neurons. By the time these books were written, forward propagation and backpropagation were well worked out."], "ref": "Lecture 17 · p2", "media": {"image": "assets/slides/lecture17/002.webp", "caption": "Lecture 17 · p2"}}, {"main": "**The vowel network takes one static vector and makes one decision.** A **static** vector is a fixed list of numbers from one moment in time. But speech changes all the time, and a sentence is many words, one after another.", "sub": ["So one fixed list of numbers cannot model thinking that unfolds over time."], "ref": "Lecture 17 · p2", "media": {"image": "assets/slides/lecture17/002.webp", "caption": "Lecture 17 · p2"}}, {"main": "**A recurrent network sends its own output back into part of its input, so what it produces at one moment helps predict the next moment.** **Michael Jordan** built the **recurrent** network to model speech production. He built it because features such as nasality and lip rounding switch on and off at different moments.", "sub": ["**Plan units** hold what the network is supposed to say, and **state units** hold a copy of the last output. Both send their values to the hidden layer, and the hidden layer sends its values to the output.", "The output is copied back into the state units. The same weights are used at every step."], "end": "So a recurrent network can work through a sequence, instead of handling only one static vector.", "ref": "Lecture 17 · p3", "media": {"image": "assets/slides/lecture17/003.webp", "caption": "Lecture 17 · p3"}}, {"main": "**GPT works the same way as the recurrent network, one word at a time.** It predicts the next word and adds that word to the prompt. Then it uses the whole prompt, including the new word, as input to predict the word after that.", "sub": ["The main steps in this history are 1943 (the McCulloch and Pitts paper), 1985 (backpropagation) and 2017 (the design behind GPT)."], "ref": "Lecture 17 · p3", "media": {"image": "assets/slides/lecture17/003.webp", "caption": "Lecture 17 · p3"}}], "questions": [{"source": "Predicted (Lectures 17–18) 1", "q": "How does the all-or-none behavior of neurons connect to the sigmoid?", "a": "The all-or-none behavior of neurons is the same idea as the sigmoid. This is because a real neuron is either firing or not firing. The sigmoid turns an inner product into a number near 0 (off) or near 1 (on), with a steep change in between. So an artificial neuron that uses the sigmoid behaves the same way as a real neuron."}, {"source": "Predicted (Lectures 17–18) 2", "q": "What do parallel and distributed mean in Parallel Distributed Processing?", "a": "Parallel means that many neurons calculate their activations at the same time.\n\nDistributed means that the information from the inputs is spread across all the neurons. So the information is not stored in one place."}, {"source": "Predicted (Lectures 17–18) 3", "q": "What does a single neuron take in and give back? What about a neural network?", "a": "A single neuron takes in a vector and gives back one number. That number is the inner product, which is each input multiplied by its weight, with the results added together.\n\nA neural network takes in one vector and gives back a vector of decisions. This is because a neural network repeats the inner product layer after layer. So the network ends with several outputs instead of just one number."}, {"source": "Predicted (Lectures 17–18) 4", "q": "Why can't the vowel network model a sentence or speech over time?", "a": "The vowel network cannot model a sentence or speech over time because it takes one static vector and makes one decision. That vector is F1 and F2 (the first two formants) from one moment. But speech changes all the time, and a sentence is many words, one after another. So modeling speech needs a network that works through a sequence."}, {"source": "Predicted (Lectures 17–18) 5", "q": "What makes Jordan's network recurrent, and why did he build it?", "a": "Jordan's network is recurrent because it sends its own output back into part of its input. It copies the output into the state units. So what it produced at one moment helps predict the next moment.\n\nJordan built it because speech production changes over time. Features such as nasality and lip rounding switch on and off at different moments. So he needed a network that could follow these changes step by step."}, {"source": "Predicted (Lectures 17–18) 6", "q": "How is a recurrent network different from an nn.Sequential network?", "a": "A recurrent network is different from an nn.Sequential network because it loops its output back into its input. A Sequential network passes the input through the layers once, from the input to the output, and makes one decision. A recurrent network sends its output back in as part of its next input. So a recurrent network works through a sequence step by step."}, {"source": "Predicted (Lectures 17–18) 7", "q": "How does GPT use the same idea as Jordan's network?", "a": "GPT uses the same idea as Jordan's network because it also feeds its own output back into its input. It predicts the next word and adds that word to the prompt. Then it predicts again, using the longer prompt. So GPT produces text one word at a time."}]}, {"id": "m3-llm-sequences", "tier": "Kept for the final", "lectures": "Lectures 17 and 18 · repeated in Lecture 19", "title": "From the vowel network to an LLM: many vectors in, the next item out", "note": "", "blocks": [{"main": "**An LLM (large language model) is given a sequence of vectors (lists of numbers) and predicts the next one.** For example, it is given 15 vectors and predicts the sixteenth. The sixteenth is a probability distribution (a list of how likely each option is) over what could come next, such as each of about 30,000 English words.", "sub": ["The vectors can be words, frames of a spectrogram (short time slices of a display of a sound's frequencies), patches of an image or the amino acids of a protein.", "The LLM only ever works with lists of numbers, so the same design works for all of them."], "ref": "Lecture 17 · p5 · Lecture 18 · p5 · Lecture 19 · p5", "media": {"image": "assets/slides/lecture17/005.webp", "caption": "Lecture 17 · p5"}}, {"main": "**Language depends on connections between words that are far apart.** In \"the dog that my parents, who I love very much, ...\", the next word is **barks**. Barks goes with the singular word dog, no matter how many words come in between.", "sub": ["An LLM learns this from data, not from a rule someone teaches it."], "ref": "Lecture 17 · p4 · Lecture 18 · p2 · Lecture 19 · p2", "media": {"image": "assets/slides/lecture17/004.webp", "caption": "Lecture 17 · p4"}}, {"main": "**An LLM learns by predicting the next word, such as mat after \"the cat sat on the\".** When the prediction is wrong, backpropagation adjusts the weights. This is repeated with a huge number of sentences.", "sub": ["Underneath everything, **inference** (using the network to make a prediction) is done with inner products. Learning is done with stochastic gradient descent plus **dynamic programming** (reusing calculations already done, which is how backpropagation works backward through the layers).", "An LLM predicts from past data. So when something is not covered by its data, it can make things up, which is called **hallucination**."], "ref": "Lecture 17 · p4 · Lecture 18 · p2 · Lecture 19 · p2", "media": {"image": "assets/slides/lecture17/004.webp", "caption": "Lecture 17 · p4"}}], "questions": [{"source": "His question 1", "q": "What is the difference between the input and output of the vowel network and those of an LLM?", "a": "The difference is that the vowel network takes in one vector and decides among five categories, while an LLM takes in many vectors and decides among a whole vocabulary.\n\nThe vowel network's input is one vector, F1 and F2. Its output decides among five categories.\n\nAn LLM's input is many vectors in sequence, such as the words so far. Its output decides among a whole vocabulary for the next item."}, {"source": "Predicted (Lectures 17–18) 8", "q": "An LLM is given 15 vectors and predicts the sixteenth. Name three things the vectors can stand for.", "a": "Three things the vectors can stand for are the words of a sentence, the frames of a spectrogram and the patches of an image. They can also stand for the amino acids of a protein. The same kind of prediction works for all of them. This is because the LLM only works with lists of numbers, whatever those numbers stand for."}, {"source": "Predicted (Lectures 17–18) 9", "q": "What does the sixteenth vector look like, and does it add up to anything?", "a": "The sixteenth vector is a probability distribution over what could come next, and its numbers add up to one.\n\nThe sixteenth vector has one number for each possible next item, such as each English word. Each number is how likely that item is to come next.\n\nIt adds up to one because it is a probability distribution. The probabilities of all the possible next items always add up to one."}, {"source": "Predicted (Lectures 17–18) 10", "q": "Why is the next word barks and not bark in \"the dog that my parents, who I love very much, ... \"?", "a": "The next word is barks and not bark because barks goes with the singular word dog. This is true no matter how many words come in between. It holds even when the plural word parents comes in between. To predict barks, an LLM has to use a word far back in the sequence. It learns to do this from data, by computing inner products layer after layer."}, {"source": "Predicted (Lectures 17–18) 11", "q": "Why can an LLM hallucinate?", "a": "An LLM can hallucinate because it predicts from past data. When it meets something its data does not cover, its prediction can turn into a guess. So it can make things up, and this is called hallucination."}]}, {"id": "m3-gestalt-cloze", "tier": "Kept for the final", "lectures": "Lecture 17 · repeated in Lecture 19", "title": "Gestalt completion and the cloze test", "note": "", "blocks": [{"main": "**Gestalt psychology studies how people see whole patterns.** In the Gestalt figure, people see a triangle even though no triangle is drawn. They see it because a large part of human knowledge is completing what is missing.", "sub": ["**Closure** is the Gestalt term for completing a familiar pattern that is not quite finished. For example, people see a broken circle as a whole circle."], "ref": "Lecture 17 · p5 · Lecture 18 · p5 · Lecture 19 · p5", "media": {"image": "assets/slides/lecture17/005.webp", "caption": "Lecture 17 · p5"}}, {"main": "**In a cloze test, words are removed from a text, and people fill them in.** The name cloze comes from closure. The test measures knowledge by asking someone to complete a sequence.", "sub": ["An LLM (large language model) that predicts the next word is doing a cloze test again and again."], "end": "So training a system only to predict the missing piece turns out to copy human thinking.", "ref": "Lecture 17 · p5 · Lecture 18 · p5 · Lecture 19 · p5", "media": {"image": "assets/slides/lecture17/005.webp", "caption": "Lecture 17 · p5"}}], "questions": [{"source": "Predicted (Lectures 17–18) 12", "q": "Describe the Gestalt principle of closure, and how an LLM uses it to learn.", "a": "The Gestalt principle of closure is completing a familiar pattern that is not quite finished. For example, people see a triangle where none is drawn, and they see a broken circle as a whole circle.\n\nAn LLM (large language model) uses closure to learn by doing the same kind of completion. It predicts the missing next piece of a sequence again and again. When its prediction is wrong, it corrects its weights. So it learns by completing sequences over and over."}, {"source": "Predicted (Lectures 17–18) 13", "q": "What is a cloze test, and why is an LLM's training like one?", "a": "A cloze test is a test where words are removed from a text and people fill them in. So it tests knowledge by asking someone to complete a sequence.\n\nAn LLM's training is like a cloze test because the LLM (large language model) is trained by filling in the next word over and over. So for an LLM, knowing something means being able to complete the sequence."}, {"source": "Predicted (Lectures 17–18) 14", "q": "Why do people see a triangle in the Gestalt figure?", "a": "People see a triangle in the Gestalt figure because they complete the missing parts of a familiar pattern. No triangle is actually drawn, but people fill in what is missing. This completion is the Gestalt principle of closure.", "img": "assets/exam2/gen-kanizsa-triangle.svg", "alt": "Three black circles with wedges cut out, facing each other"}]}, {"id": "m3-heads-layers", "tier": "Kept for the final", "lectures": "Lecture 18 · repeated in Lecture 19", "title": "Heads and layers", "note": "", "blocks": [{"main": "**An LLM (large language model) is built from layers, and each layer contains heads.** A **layer** is one round of improving the vectors (the lists of numbers that represent the words). The layers come one after another from the input to the output. A **head** is one expert, and it is a set of weights. The heads sit side by side inside each layer.", "sub": ["Each head gives its own opinion on how to improve the vectors.", "The layer combines the opinions of all its heads into improved vectors. Then the next layer does the same thing again with those improved vectors."], "ref": "Lecture 18 · p3 · Lecture 19 · p3", "media": {"image": "assets/slides/lecture18/003.webp", "caption": "Lecture 18 · p3"}}, {"main": "**Heads and layers work like visiting a series of classes to improve yourself.** The classes you visit one after another are the **layers**. The students in each class, who each give you an opinion, are the **heads**.", "sub": ["Layers give an LLM **depth**, which means one round of improvement after another.", "Heads give an LLM **width**, which means many experts are asked at the same time in each round."], "ref": "Lecture 18 · p3 · Lecture 19 · p3", "media": {"image": "assets/slides/lecture18/003.webp", "caption": "Lecture 18 · p3"}}, {"main": "**Predicting the next word is so hard that large systems have a hundred or more layers, with about a hundred heads in each layer.** Every one of those heads learns.", "sub": ["If the predicted next word is wrong, every head in every layer adjusts its weights using backpropagation (the method that calculates how much each weight contributed to the error). This makes the next prediction closer to the right word."], "ref": "Lecture 18 · p3 · Lecture 19 · p3", "media": {"image": "assets/slides/lecture18/003.webp", "caption": "Lecture 18 · p3"}}], "questions": [{"source": "His question 2", "q": "What are heads, and how do they relate to layers?", "a": "A head is one expert, which is a set of weights that gives its own opinion on how to improve the vectors. Heads sit side by side inside each layer. The layer combines all of its heads' opinions into improved vectors. The layers come one after another from the input to the output. So each layer uses its heads to improve the vectors again."}, {"source": "Predicted (Lectures 17–18) 15", "q": "In the classroom of experts, what are the classes and what are the students?", "a": "In the classroom of experts, the classes are the layers and the students are the heads. This is because you visit the classes one after another, just as the layers come one after another. The students in each class each give a separate opinion at the same time, just as the heads in one layer work side by side. You combine those opinions before moving on to the next class. So each class is one layer, and each student in it is one head."}, {"source": "Predicted (Lectures 17–18) 16", "q": "Which gives an LLM depth and which gives it width, heads or layers?", "a": "Layers give an LLM depth, and heads give it width. This is because layers are rounds of improvement that come one after another, which adds depth. Heads work side by side inside the same layer, which adds width. So more layers means more rounds, and more heads means more experts in each round."}, {"source": "Predicted (Lectures 17–18) 17", "q": "An LLM has 5 layers with 4 heads in each layer. How many heads does it have, and which of them work at the same time?", "a": "The LLM has 20 heads, and the 4 heads inside the same layer work at the same time. This is because each of the 5 layers has 4 heads, and 5 times 4 is 20. The 4 heads inside one layer work side by side. The layers come one after another, so layer 2 works on the vectors that layer 1 improved. So heads in the same layer work at the same time, but heads in different layers do not."}, {"source": "Predicted (Lectures 17–18) 18", "q": "The LLM predicts bark instead of barks after \"the dog that my parents ... \". Which weights change?", "a": "When the LLM predicts bark instead of barks, the weights of every head in every layer change. This is because backpropagation calculates how much each weight contributed to the wrong prediction. Then each weight is adjusted a little in the direction that reduces the error. So the next prediction is closer to barks."}, {"source": "Predicted (Lectures 17–18) 19", "q": "Where is the knowledge of an LLM stored?", "a": "The knowledge of an LLM is stored in its weights. This is because each head is a set of weights, and those weights are what change when the model learns. So the knowledge is spread across all the heads in all the layers. The vowel network's knowledge is stored in its weights in the same way."}]}, {"id": "m3-recurrent-dynamical", "tier": "Kept for the final", "lectures": "Lectures 17 and 18 · repeated in Lecture 19", "title": "The LLM as a dynamical system", "note": "", "blocks": [{"main": "**A dynamical system is a rule that is given its own output as input again and again.** Numbers go in, the rule changes them, and new numbers come out. The output then becomes the next input.", "sub": ["In the **harmonic oscillator** (a mass on a spring moving back and forth), the two numbers are position and velocity (speed and direction). They take turns updating.", "When the rule is repeated step by step, the position traces out a **cosine** shape."], "ref": "Lecture 18 · p4 · Lecture 19 · p4", "media": {"image": "assets/slides/lecture18/004.webp", "caption": "Lecture 18 · p4"}}, {"main": "**An LLM (large language model) can be treated as a dynamical system.** Each layer is the rule, and the depth of the layers plays the role of time. The input vectors are the **initial conditions** (the starting numbers).", "sub": ["Each layer turns the vectors into better vectors, until the last layer can predict the next word.", "Each layer has its own learned weights. So each step passes its output to the next step, but each step uses different weights."], "end": "So in both systems, the output of one step is the input to the next step.", "ref": "Lecture 18 · p4 · Lecture 19 · p4", "media": {"image": "assets/slides/lecture18/004.webp", "caption": "Lecture 18 · p4"}}], "questions": [{"source": "Predicted (Lectures 17–18) 20", "q": "Why is an LLM called a dynamical system?", "a": "An LLM is called a dynamical system because it works by giving a rule its own output again and again. A dynamical system is a rule that is repeatedly given its own output as input, starting from initial conditions (the starting numbers). In an LLM, the input vectors are the initial conditions. Each layer applies its weights to turn those vectors into better vectors, and the next layer takes those as its input. So the depth of the layers plays the role of time."}, {"source": "Predicted (Lectures 17–18) 21", "q": "In the harmonic oscillator, which two numbers update, and in what order?", "a": "In the harmonic oscillator, position x and velocity v update, and they take turns. First, the new x is calculated from the old v. Then, the new v is calculated from the new x. When these two steps are repeated over and over, x traces out a cosine shape."}]}, {"id": "m3-phonotactics", "tier": "Kept for the final", "lectures": "Lectures 17 and 18 · repeated in Lecture 19", "title": "Phonotactics and guessing the next letter", "note": "", "blocks": [{"main": "**Phonotactics are the rules for which sounds can follow which in a language.** Every speaker knows them without being taught. A simple English syllable is a consonant, a vowel and a consonant, as in **Don** or **cup**.", "sub": ["Mat, sit, dog, fish and shave are also consonant, vowel, consonant.", "The pattern is about sounds, not letters. So the silent e at the end of shave does not count, because it makes no sound.", "Ship, chin and bath also count. This is because sh, ch and th are each one sound, even though each is spelled with two letters."], "ref": "Lecture 17 · p6 · Lecture 18 · p6 · Lecture 19 · p6", "media": {"image": "assets/slides/lecture17/006.webp", "caption": "Lecture 17 · p6"}}, {"main": "**Consonants can also form clusters (groups of consonants in a row) before or after the vowel.** A cluster before the vowel is an **onset**, as in split, flat, black and glad. A cluster after the vowel is a **coda**, as in desk, help, milk and lamp.", "sub": ["The order of the consonants is a mirror image around the vowel. For example, l sits right next to the vowel in both flat and help. So flat is a word, and lfat is impossible.", "Each real word has an impossible version that puts the wrong consonant next to the vowel, such as help and hepl, or lamp and lapm.", "Sblit and desb are impossible too. That is why a product called desb would sound un-English."], "ref": "Lecture 17 · p6 · Lecture 18 · p6 · Lecture 19 · p6", "media": {"image": "assets/slides/lecture17/006.webp", "caption": "Lecture 17 · p6"}}, {"main": "**A pair of consonants can be fine across a syllable break but impossible at the start of a syllable.** Atlantic is a word because t and l are on opposite sides of a syllable break (At-lan-tic). Tlantic is impossible because tl cannot start an English syllable.", "sub": ["The sound ng can end a syllable, but it can never start one."], "ref": "Lecture 17 · p6 · Lecture 18 · p6 · Lecture 19 · p6", "media": {"image": "assets/slides/lecture17/006.webp", "caption": "Lecture 17 · p6"}}, {"main": "**Each language has its own phonotactics.** Mandarin allows only nasal sounds (sounds made with air going out through the nose, like n and ng) at the end of a syllable. Russian and Polish allow clusters like zb or dl at the start of a word.", "sub": ["Spanish speakers add an e before st at the start of a word, as in estadio."], "ref": "Lecture 17 · p6 · Lecture 18 · p6 · Lecture 19 · p6", "media": {"image": "assets/slides/lecture17/006.webp", "caption": "Lecture 17 · p6"}}, {"main": "**Guessing the next letter of a word depends on phonotactics, and each guess is a probability distribution.** After a vowel, almost any letter can come next, so the distribution is **flat** (the probability is spread out over many letters). At the start of a word, the choices narrow down to what an English onset allows.", "sub": ["After ra, almost any letter can come next, such as t, n, r or l, so the distribution is flat.", "After skr, the distribution is **sharply peaked** (most of the probability goes to a few vowels)."], "end": "So a GPT trained only on this guessing game learns English syllable structure. This is because guessing the next letter is the same task as an LLM predicting the sixteenth item from the first fifteen.", "ref": "Lecture 17 · p7 · Lecture 18 · p7 · Lecture 19 · p7", "media": {"image": "assets/slides/lecture17/007.webp", "caption": "Lecture 17 · p7"}}, {"main": "**At the start of a word, each first letter or cluster allows only a few next letters.** After sp, only l, r or a vowel can come next, never n. After k, a vowel or n can come next, as in knee, but never t.", "sub": ["After b or f, only r, l or a vowel can come next, never n.", "After sh, only a vowel or r can come next, as in shrimp.", "After skr, or after m at the start of a word, only a vowel can come next."], "ref": "Lecture 17 · p7 · Lecture 18 · p7 · Lecture 19 · p7", "media": {"image": "assets/slides/lecture17/007.webp", "caption": "Lecture 17 · p7"}}, {"main": "**Inside a word, the letters so far can make one next letter almost certain.** After bram, the next letter is almost certainly b, as in bramble.", "sub": ["A new syllable could also start there, so b is not the only possible next letter."], "ref": "Lecture 17 · p7 · Lecture 18 · p7 · Lecture 19 · p7", "media": {"image": "assets/slides/lecture17/007.webp", "caption": "Lecture 17 · p7"}}, {"main": "**After pl, st and th at the start of a word, the next letter is limited too.** After pl, only a vowel can come next, as in play. After st, a vowel or r can come next, as in star and street, but not l or k.", "sub": ["After th, r, w or a vowel can come next, as in three, thwart and thin, but not l or n."], "ref": "Lecture 17 · p7 · Lecture 18 · p7 · Lecture 19 · p7", "media": {"image": "assets/slides/lecture17/007.webp", "caption": "Lecture 17 · p7"}}], "questions": [{"source": "His question 3", "q": "Which could be English words: blick, bnick, sblat, splat, dlag, lisk, lisb, lapm, lamp? For each one that could not, name the problem.", "a": "Blick, splat, lisk and lamp could be English words.\n\nBnick, sblat and dlag could not be English words. This is because bn, sb and dl cannot start a syllable in English.\n\nLisb and lapm could not be English words. This is because sb and pm cannot end a syllable in English."}, {"source": "His question 4", "q": "Each of these starts an English word: pl_, st_ and th_. What could come next, and what could not?", "a": "After pl, only a vowel can come next, as in play. So a consonant such as n cannot come next.\n\nAfter st, a vowel or r can come next, as in star and street. But l and k cannot come next.\n\nAfter th, r, w or a vowel can come next, as in three, thwart and thin. But l and n cannot come next."}, {"source": "Predicted (Lectures 17–18) 22", "q": "After which start is the next-letter distribution flatter, ra_ or skr_? Why?", "a": "The next-letter distribution is flatter after ra than after skr. This is because ra ends in a vowel, and after a vowel almost any letter can come next. So the probability is spread out over many letters. After skr, only a vowel can come next. So most of the probability goes to a few vowels, and the distribution is sharply peaked."}, {"source": "Predicted (Lectures 17–18) 23", "q": "Why is Atlantic an English word but tlantic impossible?", "a": "Atlantic is an English word, but tlantic is impossible. This is because in Atlantic, the t and l are on opposite sides of a syllable break (At-lan-tic), so each syllable follows the rules. In tlantic, tl would have to start a syllable. English does not allow tl at the start of a syllable, so tlantic is impossible."}, {"source": "Predicted (Lectures 17–18) 24", "q": "Could ngop be an English word? Could flim?", "a": "Ngop could not be an English word. This is because the sound ng can end a syllable, as in ring, but it can never start one.\n\nFlim could be an English word. This is because fl is an allowed onset (the consonants before the vowel), as in flat, and im is an allowed ending."}, {"source": "Predicted (Lectures 17–18) 25", "q": "Why does a GPT trained only to guess the next letter end up knowing English syllable structure?", "a": "A GPT trained only to guess the next letter ends up knowing English syllable structure because the patterns of English syllables determine which letters can come next. This is because its guesses can only get better by matching those patterns. So as it learns, its probability distributions take on the shape of those patterns. They are flat after a vowel and sharply peaked after a start such as skr."}, {"source": "Predicted (Lectures 17–18) 26", "q": "Which letter cannot come next after sp_ at the start of a word: l, r, n or a?", "a": "N cannot come next after sp at the start of a word. This is because spn is not an allowed English onset (the consonants before the vowel). After sp, only l, r or a vowel can come next, as in split, spring and spa."}, {"source": "Predicted (Lectures 17–18) 27", "q": "Which letter cannot come next after k_ at the start of a word: a, n or t?", "a": "T cannot come next after k at the start of a word. This is because kt cannot start an English syllable. After k, a vowel or n can come next, as in knee."}, {"source": "Predicted (Lectures 17–18) 28", "q": "What can come next after b_ or f_ at the start of a word, and what cannot?", "a": "After b or f at the start of a word, only r, l or a vowel can come next, as in bring, black, frog and flat. N cannot come next. This is because bn and fn cannot start an English syllable."}, {"source": "Predicted (Lectures 17–18) 29", "q": "What can come next after sh_ at the start of a word?", "a": "After sh at the start of a word, only a vowel or r can come next, as in ship and shrimp. This is because shr is the only consonant cluster that English allows starting with sh."}, {"source": "Predicted (Lectures 17–18) 30", "q": "What can come next after skr_?", "a": "After skr, only a vowel can come next, as in scream and scrap (where the skr sound is spelled scr). This is because skr already fills the whole onset (the consonants before the vowel). So no other consonant can be added before the vowel."}, {"source": "Predicted (Lectures 17–18) 31", "q": "Why are lfat, hepl and lapm impossible when flat, help and lamp are words?", "a": "Lfat, hepl and lapm are impossible because the order of a cluster is a mirror image around the vowel. In flat and help, the l sits right next to the vowel. In lamp, the m sits right next to the vowel. Each impossible version puts the wrong consonant next to the vowel. So it breaks the mirror order, and it cannot be an English word."}, {"source": "Predicted (Lectures 17–18) 32", "q": "Is ship a consonant, vowel, consonant word even though it has four letters?", "a": "Yes, ship is a consonant, vowel, consonant word even though it has four letters. This is because the pattern is about sounds, not letters, and sh is one sound. So ship is the consonant sh, the vowel i and the consonant p."}]}, {"id": "m3-agentic", "tier": "Kept for the final", "lectures": "Lectures 17 and 18 · repeated in Lecture 19", "title": "Agentic systems and Software 3.0", "note": "", "blocks": [{"main": "**An agentic system is a group of LLMs (large language models) connected so that one LLM's output becomes the next LLM's input.** In AI today, an **agent** is just an LLM. In one example, an outline LLM plans the answer, and a writing LLM writes it.", "sub": ["A critic LLM checks the draft, and a revision LLM works back and forth with the critic.", "A final LLM produces the answer that the user sees."], "ref": "Lecture 17 · p4 · Lecture 18 · p2 · Lecture 19 · p2", "media": {"image": "assets/slides/lecture17/004.webp", "caption": "Lecture 17 · p4"}}, {"main": "**The critic loop sends the draft back and forth between the critic and the reviser.** The loop continues until the critic is satisfied or a limit is reached. This loop greatly reduced **hallucination** (when an LLM makes up false statements).", "sub": ["Once each LLM is trained, its weights usually do not change.", "The agents share a common memory, where they write and read information."], "ref": "Lecture 17 · p4 · Lecture 18 · p2 · Lecture 19 · p2", "media": {"image": "assets/slides/lecture17/004.webp", "caption": "Lecture 17 · p4"}}, {"main": "**Software 1.0, 2.0 and 3.0 are three ways to build a program.** **Software 1.0** is writing a program in a programming language such as Python. **Software 2.0** is training a neural network on input and output data, so the program is the network's weights.", "sub": ["**Software 3.0** is having an agentic system build and run the program from instructions written in plain English.", "Building a program this way is called **vibe coding**."], "ref": "Lecture 18 · p8 · Lecture 19 · p8", "media": {"image": "assets/slides/lecture18/008.webp", "caption": "Lecture 18 · p8"}}], "questions": [{"source": "His question 5", "q": "What is an agentic system, in terms of LLMs? Describe the example system.", "a": "An agentic system is a graph (a set of connected parts) of LLMs (large language models), each with its own job. The LLMs are connected so that one LLM's output becomes the next LLM's input.\n\nIn the example system, one LLM outlines, one writes, one critiques, one revises and one produces the final version. The critic and the reviser form a loop. So the draft keeps going back until the critic is satisfied or the limit is reached."}, {"source": "His question 6", "q": "What does the critic loop do, and what does it prevent that was common in earlier LLMs?", "a": "The critic loop sends the draft back and forth between the critic and the reviser until the critic is satisfied. The critic checks each draft, and the reviser fixes the errors the critic finds. So errors are caught and fixed before the answer is shown to the user.\n\nThe critic loop prevents hallucination (when an LLM makes up false statements), which was a common problem in earlier LLMs."}, {"source": "Predicted (Lectures 17–18) 33", "q": "What would happen if the critic LLM were removed?", "a": "If the critic LLM were removed, the draft would go straight from writing to the final answer without being checked. This is because the critic is the LLM that checks the draft. So more made-up statements would reach the user. The critic loop is what greatly reduced hallucination, so without it that reduction would be lost."}, {"source": "Predicted (Lectures 17–18) 34", "q": "What is the difference between Software 2.0 and Software 3.0?", "a": "The difference between Software 2.0 and Software 3.0 is how the program gets built.\n\nIn Software 2.0, a neural network is trained on input and output data, so the program is the network's weights.\n\nIn Software 3.0, an agentic system builds and runs the program from plain English instructions. Building a program this way is called vibe coding."}]}, {"id": "m3-hidden-word", "tier": "New on November 17", "lectures": "Lecture 19", "title": "What an LLM learns: guessing a hidden word", "note": "", "blocks": [{"ref": "Lecture 19 · p9", "main": "**An LLM (large language model) learns by guessing a hidden word and then changing its weights a little.** In the sentence \"The chef cracks the,\" the last word is hidden. The model reads the four words before the gap. Then it has to predict the word that fills the gap.", "sub": ["Each word before the gap gives a clue about the hidden word. These clue relationships are called **interdependencies** (one part of a sequence helps predict another part).", "The model does not know the answer, so it spreads its bets. A bet is the probability the model gives to one word. It bets the most on \"egg,\" less on \"nut\" and the least on \"code.\"", "**Learning means nudging the weights (changing each weight a little) so that these guesses get better.** After the true word is revealed, the weights change a little. Because of that change, the right word gets a bigger bet next time."], "end": "The same idea holds when the signal (the sequence the model reads) contains words, sounds and images. The model still guesses a hidden piece and nudges its weights, so the way it learns stays the same.", "media": {"image": "assets/slides/lecture19/009.webp", "caption": "Lecture 19 · p9"}}], "questions": [{"source": "Predicted (Lecture 19) 1", "q": "How does an LLM learn from the sentence \"The chef cracks the ?\"", "a": "An LLM learns from this sentence by guessing the hidden last word and then changing its weights a little.\n\nThis is because each word before the gap gives a clue about the hidden word. So the model bets the most on \"egg,\" less on \"nut\" and the least on \"code.\" When the true word is revealed, the weights are nudged. So the right word gets a bigger bet next time."}, {"source": "Predicted (Lecture 19) 2", "q": "Why does the model give \"egg,\" \"nut\" and \"code\" different bets instead of one answer?", "a": "The model gives three different bets because it does not know the hidden word. All three words could follow \"The chef cracks the.\" The words before the gap make \"egg\" the most likely. So \"egg\" gets the largest bet, \"nut\" gets a smaller bet and \"code\" gets the smallest bet."}, {"source": "Predicted (Lecture 19) 3", "q": "What does learning change in an LLM, and in which direction?", "a": "Learning changes the weights. Each weight is nudged, which means it changes a little. The weights change in the direction that gives the right word a bigger bet the next time."}]}, {"id": "m3-conversion", "tier": "New on November 17", "lectures": "Lecture 19", "title": "Turning speech and images into rows of vectors", "note": "", "blocks": [{"ref": "Lecture 19 · p10", "main": "**An LLM can only read a row of vectors (lists of numbers), so speech and images have to be converted first.** Text, speech and images arrive in three different forms.", "sub": ["**Text** is already a row of pieces, such as \"Now,\" \"crack,\" \"the\" and \"egg,\" and each piece can become one vector.", "**Speech** is air pressure changing in time, and there are no words in the sound itself.", "An **image** is a grid of light, and it contains no words either."], "end": "So the first job is a conversion. Speech and images both have to become rows of vectors, because that is all the LLM can read.", "media": {"image": "assets/slides/lecture19/010.webp", "caption": "Lecture 19 · p10"}}, {"ref": "Lecture 19 · p11", "main": "**Speech is turned into a row of vectors by slicing it in time.** The sound is cut into short slices, and each slice is called a **frame**. Each slice is about 20 milliseconds long.", "sub": ["The slices go through a **speech encoder** (a neural network that was trained on a large amount of audio). One vector comes out for each slice.", "**One second of speech becomes 50 vectors.** This is because each slice is about 20 milliseconds long, and 50 slices of that length fill one second. Each slice gives one vector.", "The vectors stay in time order. The first slice gives the first vector, and the last slice gives the last vector."], "end": "So speech is now a row, just like a sentence, and the LLM can read it one vector after another.", "media": {"image": "assets/slides/lecture19/011.webp", "caption": "Lecture 19 · p11"}}, {"ref": "Lecture 19 · p12", "main": "**An image is turned into a row of vectors by cutting it into patches.** A **patch** is one small square of the image. A grid cuts the image of an egg in a pan into 16 patches.", "sub": ["The patches are laid out in a row in **reading order** (left to right along the top, then left to right along the next line down). This turns the image into a sequence, like a sentence.", "The patches go through a **vision encoder**. One vector comes out for each patch, so 16 patches give 16 vectors.", "Real systems use much smaller patches of 14 to 16 pixels. Smaller patches mean more patches for the same image, so one image gives hundreds of vectors."], "end": "So both conversions follow the same steps. The signal is cut into small pieces, the pieces are kept in order, and an encoder gives one vector for each piece.", "media": {"image": "assets/slides/lecture19/012.webp", "caption": "Lecture 19 · p12"}}], "questions": [{"source": "Predicted (Lecture 19) 4", "q": "Why is text easier for an LLM to read than speech or an image?", "a": "Text is easier because it is already a row of pieces. Each piece, such as \"Now,\" \"crack,\" \"the\" or \"egg,\" can become one vector.\n\nSpeech is air pressure changing in time, and an image is a grid of light. Neither one contains words or separate pieces. So both have to be converted into rows of vectors first."}, {"source": "Predicted (Lecture 19) 5", "q": "How is speech turned into a row of vectors?", "a": "Speech is turned into a row of vectors by slicing it in time. First, the sound is cut into short slices called frames, each about 20 milliseconds long. Then the slices go through a speech encoder, which is a neural network trained on a large amount of audio. One vector comes out for each slice, and the vectors stay in time order."}, {"source": "Predicted (Lecture 19) 6", "q": "Why does one second of speech become 50 vectors?", "a": "One second of speech becomes 50 vectors because each slice gives one vector. Each slice is about 20 milliseconds long, and 50 slices of that length fill one second. So one second gives 50 vectors."}, {"source": "Predicted (Lecture 19) 7", "q": "How is an image turned into a row of vectors?", "a": "An image is turned into a row of vectors by cutting it into patches. First, a grid cuts the image into small squares called patches. Then the patches are laid out in a row in reading order, so the image becomes a sequence. Last, a vision encoder gives one vector for each patch."}, {"source": "Predicted (Lecture 19) 8", "q": "The egg example gives 16 vectors. Why does one image give hundreds of vectors in real systems?", "a": "One image gives hundreds of vectors in real systems because real systems use much smaller patches. Their patches are only 14 to 16 pixels. Smaller patches mean more patches for the same image. Each patch gives one vector, so there are hundreds of vectors."}, {"source": "Predicted (Lecture 19) 9", "q": "What is the similarity between converting speech and converting an image, and what is the difference?", "a": "The similarity is that both are cut into small pieces, the pieces are kept in order, and an encoder gives one vector for each piece.\n\nThe difference is what is cut. Speech is cut in time into frames of about 20 milliseconds. An image is cut in space into square patches, which are then placed in reading order."}]}, {"id": "m3-one-row", "tier": "New on November 17", "lectures": "Lecture 19", "title": "One row, three senses: cross-modal dependencies", "note": "", "blocks": [{"ref": "Lecture 19 · p13", "main": "**Image patches, speech frames and words can all be placed in one row, and the model guesses the hidden piece.** The image patches come first, the speech frames come next, and the words come last. The words are \"Now,\" \"crack\" and \"the,\" and the word after them is hidden.", "sub": ["The words before the gap still give clues, the same as in a row that holds only text.", "Clues now also come from the other senses. A patch that contains an egg helps the model guess the hidden word. The sound of cracking helps too.", "A link between two different kinds of signal is called a **cross-modal dependency**."], "end": "So the game is exactly the same as before. The only new thing is that some of the clues come from other senses.", "media": {"image": "assets/slides/lecture19/013.webp", "caption": "Lecture 19 · p13"}}, {"ref": "Lecture 19 · p14", "main": "**\"Three cute puppies\" is one event given in three forms, and training puts all three in one row.** The first form is an image of three puppies, cut into 18 patches. The second form is the phrase spoken aloud. The third form is the three written words.", "sub": ["The spoken phrase is shown as a **spectrogram** (a display of a sound laid out in time). Time runs from left to right. Higher up means a higher frequency. A darker area means more energy.", "Each thin column of the spectrogram is one frame. Each word has its own stretch of time, with \"three\" first and \"puppies\" last.", "The voice is a speech synthesizer (an MBROLA diphone voice). It is not a recording of a person."], "end": "So the image, the sound and the words are three views of one event. In training, one piece of the row is hidden, and the model has to guess it.", "media": {"image": "assets/slides/lecture19/014.webp", "caption": "Lecture 19 · p14"}}], "questions": [{"source": "Predicted (Lecture 19) 10", "q": "What is a cross-modal dependency? Give an example.", "a": "A cross-modal dependency is a link between two different kinds of signal, in which a piece from one sense helps predict a piece from another sense.\n\nFor example, in \"Now crack the ?\", an image patch that contains an egg helps the model guess the hidden word. The sound of cracking helps too."}, {"source": "Predicted (Lecture 19) 11", "q": "When image patches and speech frames are added to the row, what stays the same and what changes?", "a": "The game stays the same. The model still guesses the hidden piece from the pieces it can read, and the words before the gap still give clues.\n\nWhat changes is where some of the clues come from. Some clues now come from image patches and speech frames."}, {"source": "Predicted (Lecture 19) 12", "q": "In the spectrogram of \"three cute puppies,\" what do left to right, height and darkness mean?", "a": "Left to right is time, so \"three\" comes first and \"puppies\" comes last. Height is frequency, so higher up means a higher frequency. Darkness is energy, so a darker area means more energy. Each thin column is one frame."}, {"source": "Predicted (Lecture 19) 13", "q": "Why are the image, the spectrogram and the words called three views of one event?", "a": "They are called three views of one event because all three describe the same thing, which is three cute puppies. The image gives it as patches, the speech gives it as frames, and the text gives it as words. In training, all three go into one row."}]}, {"id": "m3-training", "tier": "New on November 17", "lectures": "Lecture 19", "title": "The three training examples: hidden word, hidden sound frame, hidden image patch", "note": "", "blocks": [{"ref": "Lecture 19 · p15", "main": "**In training example 1, the hidden piece is a word, and the image and the sound settle the guess.** The row holds the image, then the sound, then the words \"three\" and \"cute.\" The word after \"cute\" is hidden.", "sub": ["With the words alone, the bets are spread out. This is because many endings fit after \"three cute,\" such as \"kittens,\" \"puppies\" and \"babies.\"", "With the image and the sound, the bet piles up on \"puppies.\" This is because the image contains puppies, and the sound contains the spoken word \"puppies.\"", "The true word is then revealed, and the model is graded on how much it bet on that word. The model bet 0.85 on \"puppies.\""], "end": "So the nudge to the weights is small. This is because the model bet a lot on the true word, so the error is small, and a small error moves the weights only a little.", "media": {"image": "assets/slides/lecture19/015.webp", "caption": "Lecture 19 · p15"}}, {"ref": "Lecture 19 · p16", "main": "**In training example 2, the hidden piece is a frame of sound, and three clues help the model guess it.** The row is put in a new order, with the image first, then the words, then the sound. This is like teaching the model to speak a sentence it was given. The sound is predicted frame by frame, from left to right.", "sub": ["The frames already heard are the first clue. The voice and the **formants** (frequency regions with strong energy) change smoothly, so the last few frames say a lot about the next one.", "The words are the second clue. They say which sound should come next, and here it is the vowel in \"pup.\"", "The image is the third clue. It contains puppies, so it backs up the words. It is a weaker clue here.", "A frame is a column of numbers. Each number is how much energy there is in one frequency band. The guess is close to the true frame, but it is not exact."], "end": "So the error is how far each guessed number is from the true number, and that error nudges the weights.", "media": {"image": "assets/slides/lecture19/016.webp", "caption": "Lecture 19 · p16"}}, {"ref": "Lecture 19 · p17", "main": "**In training example 3, the hidden piece is a patch of the image, and the biggest error is the colour.** The row is put in a new order again, with the words first, then the sound, then the image. This is like teaching the model to draw what it was told. The patches are predicted in reading order.", "sub": ["The patches already drawn are the first clue. Above the hidden patch is background. To its left are two puppies, so the model has seen what a puppy in this image looks like.", "The words are the second clue. \"Three\" says a third puppy must appear, because only two are drawn. \"Puppies\" says to expect dog ears.", "The sound is the third clue. It carries the same words, so it backs up the text.", "The model guesses a blurry puppy ear in the average colour of the first two puppies. The true puppy is dark."], "end": "So the biggest error is the colour. This is because no clue in the words, the sound or the patches already drawn said the third puppy would be dark. Only systems that also produce images are trained this way.", "media": {"image": "assets/slides/lecture19/017.webp", "caption": "Lecture 19 · p17"}}], "questions": [{"source": "Predicted (Lecture 19) 14", "q": "How do the model's bets on the next word change when the image and the sound are added to \"three cute\"?", "a": "With the words alone, the bets are spread out over \"kittens,\" \"puppies\" and \"babies.\" This is because many endings fit after \"three cute.\"\n\nWith the image and the sound, the bet piles up on \"puppies.\" This is because the image contains puppies, and the sound contains the spoken word \"puppies.\""}, {"source": "Predicted (Lecture 19) 15", "q": "The model bet 0.85 on \"puppies,\" and the true word is \"puppies.\" Is the nudge to the weights large or small? Why?", "a": "The nudge to the weights is small. This is because the model is graded on how much it bet on the true word. It bet 0.85, which is a lot, so the error is small. A small error moves the weights only a little."}, {"source": "Predicted (Lecture 19) 16", "q": "What would happen to the nudge if the model had bet only a little on \"puppies\"?", "a": "The nudge would be larger. This is because a small bet on the true word is a large error. A larger error moves the weights more, so that the true word gets a bigger bet next time."}, {"source": "Predicted (Lecture 19) 17", "q": "Name the three clues that help the model predict a hidden sound frame, and say what each one gives.", "a": "The first clue is the frames already heard. The voice and the formants change smoothly, so the last few frames say a lot about the next one.\n\nThe second clue is the words. They say which sound should come next, which here is the vowel in \"pup.\"\n\nThe third clue is the image. It contains puppies, so it backs up the words, but it is a weaker clue here."}, {"source": "Predicted (Lecture 19) 18", "q": "What is the error when the model guesses a sound frame?", "a": "The error is how far the guess is from the true frame. A frame is a column of numbers, and each number is how much energy there is in one frequency band. The error is how far apart each guessed number is from the matching true number. That error nudges the weights."}, {"source": "Predicted (Lecture 19) 19", "q": "In training example 3, why is the colour the biggest error?", "a": "The colour is the biggest error because no clue gave the colour of the third puppy. The model guessed a puppy ear in the average colour of the first two puppies. The true puppy is dark. Nothing in the words, the sound or the patches already drawn said the third puppy would be dark."}, {"source": "Predicted (Lecture 19) 20", "q": "What do the words \"three\" and \"puppies\" tell the model about the hidden image patch?", "a": "\"Three\" tells the model that a third puppy must appear, because only two puppies have been drawn so far. \"Puppies\" tells the model to expect dog ears. So the model guesses a puppy ear for the hidden patch."}, {"source": "Predicted (Lecture 19) 21", "q": "Are all systems trained to predict image patches?", "a": "No. Only systems that also produce images are trained to predict image patches. Systems that only read images usually skip this step. This is because predicting a patch is like teaching the model to draw what it was told."}]}, {"id": "m3-clues", "tier": "New on November 17", "lectures": "Lecture 19", "title": "Every piece can be the hidden one: two kinds of clue", "note": "", "blocks": [{"ref": "Lecture 19 · p18", "main": "**Any piece of the row can be the hidden one, and each sense gives a clue for it.** The hidden piece can be a word, a sound frame or an image patch.", "sub": ["For a **hidden word**, the words \"three cute\" call for a plural noun, the sound has just spoken the word, and the image contains puppies.", "For a **hidden frame**, the words say which sound comes next, the voice and the formants carry on, and the image backs up which word is being said.", "For a **hidden patch**, the word \"three\" says one more puppy is coming, the sound gives the same words in heard form, and the fur and the background carry on."], "end": "So a clue from the same sense says how the signal continues, and clues from the other senses say what the thing is. Training on all three senses together helps, because each sense fills gaps that the others leave.", "media": {"image": "assets/slides/lecture19/018.webp", "caption": "Lecture 19 · p18"}}], "questions": [{"source": "Predicted (Lecture 19) 22", "q": "What is the difference between a clue from the same sense as the hidden piece and a clue from another sense?", "a": "A clue from the same sense mostly says how the signal continues. Grammar does this for a hidden word, smooth formants do it for a hidden frame, and fur and background do it for a hidden patch.\n\nClues from the other senses mostly say what the thing is. Here they say puppies, three of them."}, {"source": "Predicted (Lecture 19) 23", "q": "For a hidden sound frame, which clue comes from the same sense, and what does it tell the model?", "a": "The clue from the same sense is that the voice and the formants carry on from the frames already heard. It tells the model how the sound continues. The words and the image are the other senses, and they say which word is being said."}, {"source": "Predicted (Lecture 19) 24", "q": "Why does training on words, sound and images together help?", "a": "Training on all three senses together helps because each sense fills gaps that the others leave. A clue from the same sense says how the signal continues. Clues from the other senses say what the thing is. So with all three senses, the model has both kinds of clue for every hidden piece."}]}, {"id": "m3-talking-back", "tier": "New on November 17", "lectures": "Lecture 19", "title": "Talking back, what is new and what stays the same", "note": "", "blocks": [{"ref": "Lecture 19 · p19", "main": "**The model speaks by predicting codes for sound, and a decoder turns the codes back into sound.** First, sound is compressed into discrete codes (separate numbered units), such as 417, 82 and 903. Each code works like a new word added to the vocabulary.", "sub": ["The model predicts the next code exactly as it predicts the next word. So speaking is the same guessing game again.", "A **decoder** then turns the row of predicted codes back into a sound wave that can be heard."], "end": "So the model gives the codes, and the decoder gives the sound.", "media": {"image": "assets/slides/lecture19/019.webp", "caption": "Lecture 19 · p19"}}, {"ref": "Lecture 19 · p19", "main": "**Three things are new when a model is trained on words, sounds and images, and one thing stays the same.** The first new thing is a **shared currency**, in which everything becomes vectors in one row. The second is **data where the senses appear together**. The third is **a schedule that protects what was already learned**.", "sub": ["What stays the same is the learning rule, which is to find the dependencies in the signal."], "end": "So the model still guesses a hidden piece and nudges its weights. The signal has only become wider, because it now holds words, sounds and images.", "media": {"image": "assets/slides/lecture19/019.webp", "caption": "Lecture 19 · p19"}}], "questions": [{"source": "Predicted (Lecture 19) 25", "q": "How does the model talk back?", "a": "The model talks back by predicting codes for sound. First, sound is compressed into discrete codes, and each code works like a new word in the vocabulary. Then the model predicts the next code exactly as it predicts the next word. Last, a decoder turns the codes back into a sound wave."}, {"source": "Predicted (Lecture 19) 26", "q": "What three things are new when an LLM is trained on words, sounds and images?", "a": "The first new thing is a shared currency, in which everything becomes vectors in one row. The second is data where the senses appear together. The third is a schedule that protects what was already learned."}, {"source": "Predicted (Lecture 19) 27", "q": "What stays the same when the signal holds words, sounds and images?", "a": "The learning rule stays the same. The model still finds the dependencies in the signal by guessing a hidden piece and nudging its weights. The signal has only become wider."}]}]}, "module3-v2": {"label": "Module III · Study this first (Lectures 17–19, with a My notes box under each block)", "range": "Lectures 17 to 19", "split": true, "notes": true, "howToAnswer": [], "scope": {"label": "On the final", "covers": "Module III is the LLM part of the course. It holds Lectures 17 and 18, which also stay in Module II, and Lecture 19 from November 17, the first lecture after Exam 2. The final exam is cumulative, so Modules I and II come back too.", "final": "", "evidence": "On November 10 he said the review and homework questions go up to right before LLMs, and that the LLM part is kept for the final. That part is Lectures 17 and 18. Lecture 19 repeats seven Lecture 18 slides and then adds eleven new slides on training an LLM with words, sounds and images. No review sheet for the final has been handed out yet, and there is no class transcript for November 17. Every question on the new slides is marked Predicted. They are predictions, not confirmed exam questions."}, "flags": ["The notes for Lectures 17 and 18 are the same notes as on the Module II study page, shown here again and not rewritten.", "The notes for the new Lecture 19 slides come from the slides and their speaker notes only. There is no class transcript for November 17, so anything he added out loud is not here.", "The speech in the three cute puppies example was made with a speech synthesizer (an MBROLA diphone voice). It is not a recording of a person.", "The slides call the visual input the picture. These notes say image and image patch.", "The last slide lists a schedule that protects what was already learned, and it does not explain the schedule. These notes repeat the item and add nothing from outside the slides."], "topics": [{"id": "m3-lead-up", "tier": "Kept for the final", "lectures": "Lecture 17 (start) and Lecture 18", "title": "Leading up to LLMs: from one neuron to networks that unfold over time", "note": "", "blocks": [{"main": "**A neuron in an artificial neural network takes in a vector (a list of numbers) and gives back one number.** It multiplies each input by its weight and adds the results. This is called the **inner product**. A **neural network** repeats the inner product layer after layer.", "sub": ["A neural network takes in one vector and gives back a vector of decisions."], "ref": "Lecture 17 · p2", "media": {"image": "assets/slides/lecture17/002.webp", "caption": "Lecture 17 · p2"}}, {"main": "**Artificial neural networks began in biology, not in technology.** The first paper on artificial neural networks was by **McCulloch and Pitts**. It started from the all-or-none behavior of real neurons. A real neuron is either firing or not firing. This is the same idea as the **sigmoid** (a function that turns a number into a value between 0 and 1).", "sub": ["The earliest neural network work tried to model how the mind works, including mental illness.", "In the **Parallel Distributed Processing** books, **parallel** means many neurons calculate their activations at the same time.", "**Distributed** means the information from the inputs is spread across all the neurons. By the time these books were written, forward propagation and backpropagation were well worked out."], "ref": "Lecture 17 · p2", "media": {"image": "assets/slides/lecture17/002.webp", "caption": "Lecture 17 · p2"}}, {"main": "**The vowel network takes one static vector and makes one decision.** A **static** vector is a fixed list of numbers from one moment in time. But speech changes all the time, and a sentence is many words, one after another.", "sub": ["So one fixed list of numbers cannot model thinking that unfolds over time."], "ref": "Lecture 17 · p2", "media": {"image": "assets/slides/lecture17/002.webp", "caption": "Lecture 17 · p2"}}, {"main": "**A recurrent network sends its own output back into part of its input, so what it produces at one moment helps predict the next moment.** **Michael Jordan** built the **recurrent** network to model speech production. He built it because features such as nasality and lip rounding switch on and off at different moments.", "sub": ["**Plan units** hold what the network is supposed to say, and **state units** hold a copy of the last output. Both send their values to the hidden layer, and the hidden layer sends its values to the output.", "The output is copied back into the state units. The same weights are used at every step."], "end": "So a recurrent network can work through a sequence, instead of handling only one static vector.", "ref": "Lecture 17 · p3", "media": {"image": "assets/slides/lecture17/003.webp", "caption": "Lecture 17 · p3"}}, {"main": "**GPT works the same way as the recurrent network, one word at a time.** It predicts the next word and adds that word to the prompt. Then it uses the whole prompt, including the new word, as input to predict the word after that.", "sub": ["The main steps in this history are 1943 (the McCulloch and Pitts paper), 1985 (backpropagation) and 2017 (the design behind GPT)."], "ref": "Lecture 17 · p3", "media": {"image": "assets/slides/lecture17/003.webp", "caption": "Lecture 17 · p3"}}], "questions": [{"source": "Predicted (Lectures 17–18) 1", "q": "How does the all-or-none behavior of neurons connect to the sigmoid?", "a": "The all-or-none behavior of neurons is the same idea as the sigmoid. This is because a real neuron is either firing or not firing. The sigmoid turns an inner product into a number near 0 (off) or near 1 (on), with a steep change in between. So an artificial neuron that uses the sigmoid behaves the same way as a real neuron."}, {"source": "Predicted (Lectures 17–18) 2", "q": "What do parallel and distributed mean in Parallel Distributed Processing?", "a": "Parallel means that many neurons calculate their activations at the same time.\n\nDistributed means that the information from the inputs is spread across all the neurons. So the information is not stored in one place."}, {"source": "Predicted (Lectures 17–18) 3", "q": "What does a single neuron take in and give back? What about a neural network?", "a": "A single neuron takes in a vector and gives back one number. That number is the inner product, which is each input multiplied by its weight, with the results added together.\n\nA neural network takes in one vector and gives back a vector of decisions. This is because a neural network repeats the inner product layer after layer. So the network ends with several outputs instead of just one number."}, {"source": "Predicted (Lectures 17–18) 4", "q": "Why can't the vowel network model a sentence or speech over time?", "a": "The vowel network cannot model a sentence or speech over time because it takes one static vector and makes one decision. That vector is F1 and F2 (the first two formants) from one moment. But speech changes all the time, and a sentence is many words, one after another. So modeling speech needs a network that works through a sequence."}, {"source": "Predicted (Lectures 17–18) 5", "q": "What makes Jordan's network recurrent, and why did he build it?", "a": "Jordan's network is recurrent because it sends its own output back into part of its input. It copies the output into the state units. So what it produced at one moment helps predict the next moment.\n\nJordan built it because speech production changes over time. Features such as nasality and lip rounding switch on and off at different moments. So he needed a network that could follow these changes step by step."}, {"source": "Predicted (Lectures 17–18) 6", "q": "How is a recurrent network different from an nn.Sequential network?", "a": "A recurrent network is different from an nn.Sequential network because it loops its output back into its input. A Sequential network passes the input through the layers once, from the input to the output, and makes one decision. A recurrent network sends its output back in as part of its next input. So a recurrent network works through a sequence step by step."}, {"source": "Predicted (Lectures 17–18) 7", "q": "How does GPT use the same idea as Jordan's network?", "a": "GPT uses the same idea as Jordan's network because it also feeds its own output back into its input. It predicts the next word and adds that word to the prompt. Then it predicts again, using the longer prompt. So GPT produces text one word at a time."}]}, {"id": "m3-llm-sequences", "tier": "Kept for the final", "lectures": "Lectures 17 and 18 · repeated in Lecture 19", "title": "From the vowel network to an LLM: many vectors in, the next item out", "note": "", "blocks": [{"main": "**An LLM (large language model) is given a sequence of vectors (lists of numbers) and predicts the next one.** For example, it is given 15 vectors and predicts the sixteenth. The sixteenth is a probability distribution (a list of how likely each option is) over what could come next, such as each of about 30,000 English words.", "sub": ["The vectors can be words, frames of a spectrogram (short time slices of a display of a sound's frequencies), patches of an image or the amino acids of a protein.", "The LLM only ever works with lists of numbers, so the same design works for all of them."], "ref": "Lecture 17 · p5 · Lecture 18 · p5 · Lecture 19 · p5", "media": {"image": "assets/slides/lecture17/005.webp", "caption": "Lecture 17 · p5"}}, {"main": "**Language depends on connections between words that are far apart.** In \"the dog that my parents, who I love very much, ...\", the next word is **barks**. Barks goes with the singular word dog, no matter how many words come in between.", "sub": ["An LLM learns this from data, not from a rule someone teaches it."], "ref": "Lecture 17 · p4 · Lecture 18 · p2 · Lecture 19 · p2", "media": {"image": "assets/slides/lecture17/004.webp", "caption": "Lecture 17 · p4"}}, {"main": "**An LLM learns by predicting the next word, such as mat after \"the cat sat on the\".** When the prediction is wrong, backpropagation adjusts the weights. This is repeated with a huge number of sentences.", "sub": ["Underneath everything, **inference** (using the network to make a prediction) is done with inner products. Learning is done with stochastic gradient descent plus **dynamic programming** (reusing calculations already done, which is how backpropagation works backward through the layers).", "An LLM predicts from past data. So when something is not covered by its data, it can make things up, which is called **hallucination**."], "ref": "Lecture 17 · p4 · Lecture 18 · p2 · Lecture 19 · p2", "media": {"image": "assets/slides/lecture17/004.webp", "caption": "Lecture 17 · p4"}}], "questions": [{"source": "His question 1", "q": "What is the difference between the input and output of the vowel network and those of an LLM?", "a": "The difference is that the vowel network takes in one vector and decides among five categories, while an LLM takes in many vectors and decides among a whole vocabulary.\n\nThe vowel network's input is one vector, F1 and F2. Its output decides among five categories.\n\nAn LLM's input is many vectors in sequence, such as the words so far. Its output decides among a whole vocabulary for the next item."}, {"source": "Predicted (Lectures 17–18) 8", "q": "An LLM is given 15 vectors and predicts the sixteenth. Name three things the vectors can stand for.", "a": "Three things the vectors can stand for are the words of a sentence, the frames of a spectrogram and the patches of an image. They can also stand for the amino acids of a protein. The same kind of prediction works for all of them. This is because the LLM only works with lists of numbers, whatever those numbers stand for."}, {"source": "Predicted (Lectures 17–18) 9", "q": "What does the sixteenth vector look like, and does it add up to anything?", "a": "The sixteenth vector is a probability distribution over what could come next, and its numbers add up to one.\n\nThe sixteenth vector has one number for each possible next item, such as each English word. Each number is how likely that item is to come next.\n\nIt adds up to one because it is a probability distribution. The probabilities of all the possible next items always add up to one."}, {"source": "Predicted (Lectures 17–18) 10", "q": "Why is the next word barks and not bark in \"the dog that my parents, who I love very much, ... \"?", "a": "The next word is barks and not bark because barks goes with the singular word dog. This is true no matter how many words come in between. It holds even when the plural word parents comes in between. To predict barks, an LLM has to use a word far back in the sequence. It learns to do this from data, by computing inner products layer after layer."}, {"source": "Predicted (Lectures 17–18) 11", "q": "Why can an LLM hallucinate?", "a": "An LLM can hallucinate because it predicts from past data. When it meets something its data does not cover, its prediction can turn into a guess. So it can make things up, and this is called hallucination."}]}, {"id": "m3-gestalt-cloze", "tier": "Kept for the final", "lectures": "Lecture 17 · repeated in Lecture 19", "title": "Gestalt completion and the cloze test", "note": "", "blocks": [{"main": "**Gestalt psychology studies how people see whole patterns.** In the Gestalt figure, people see a triangle even though no triangle is drawn. They see it because a large part of human knowledge is completing what is missing.", "sub": ["**Closure** is the Gestalt term for completing a familiar pattern that is not quite finished. For example, people see a broken circle as a whole circle."], "ref": "Lecture 17 · p5 · Lecture 18 · p5 · Lecture 19 · p5", "media": {"image": "assets/slides/lecture17/005.webp", "caption": "Lecture 17 · p5"}}, {"main": "**In a cloze test, words are removed from a text, and people fill them in.** The name cloze comes from closure. The test measures knowledge by asking someone to complete a sequence.", "sub": ["An LLM (large language model) that predicts the next word is doing a cloze test again and again."], "end": "So training a system only to predict the missing piece turns out to copy human thinking.", "ref": "Lecture 17 · p5 · Lecture 18 · p5 · Lecture 19 · p5", "media": {"image": "assets/slides/lecture17/005.webp", "caption": "Lecture 17 · p5"}}], "questions": [{"source": "Predicted (Lectures 17–18) 12", "q": "Describe the Gestalt principle of closure, and how an LLM uses it to learn.", "a": "The Gestalt principle of closure is completing a familiar pattern that is not quite finished. For example, people see a triangle where none is drawn, and they see a broken circle as a whole circle.\n\nAn LLM (large language model) uses closure to learn by doing the same kind of completion. It predicts the missing next piece of a sequence again and again. When its prediction is wrong, it corrects its weights. So it learns by completing sequences over and over."}, {"source": "Predicted (Lectures 17–18) 13", "q": "What is a cloze test, and why is an LLM's training like one?", "a": "A cloze test is a test where words are removed from a text and people fill them in. So it tests knowledge by asking someone to complete a sequence.\n\nAn LLM's training is like a cloze test because the LLM (large language model) is trained by filling in the next word over and over. So for an LLM, knowing something means being able to complete the sequence."}, {"source": "Predicted (Lectures 17–18) 14", "q": "Why do people see a triangle in the Gestalt figure?", "a": "People see a triangle in the Gestalt figure because they complete the missing parts of a familiar pattern. No triangle is actually drawn, but people fill in what is missing. This completion is the Gestalt principle of closure.", "img": "assets/exam2/gen-kanizsa-triangle.svg", "alt": "Three black circles with wedges cut out, facing each other"}]}, {"id": "m3-heads-layers", "tier": "Kept for the final", "lectures": "Lecture 18 · repeated in Lecture 19", "title": "Heads and layers", "note": "", "blocks": [{"main": "**An LLM (large language model) is built from layers, and each layer contains heads.** A **layer** is one round of improving the vectors (the lists of numbers that represent the words). The layers come one after another from the input to the output. A **head** is one expert, and it is a set of weights. The heads sit side by side inside each layer.", "sub": ["Each head gives its own opinion on how to improve the vectors.", "The layer combines the opinions of all its heads into improved vectors. Then the next layer does the same thing again with those improved vectors."], "ref": "Lecture 18 · p3 · Lecture 19 · p3", "media": {"image": "assets/slides/lecture18/003.webp", "caption": "Lecture 18 · p3"}}, {"main": "**Heads and layers work like visiting a series of classes to improve yourself.** The classes you visit one after another are the **layers**. The students in each class, who each give you an opinion, are the **heads**.", "sub": ["Layers give an LLM **depth**, which means one round of improvement after another.", "Heads give an LLM **width**, which means many experts are asked at the same time in each round."], "ref": "Lecture 18 · p3 · Lecture 19 · p3", "media": {"image": "assets/slides/lecture18/003.webp", "caption": "Lecture 18 · p3"}}, {"main": "**Predicting the next word is so hard that large systems have a hundred or more layers, with about a hundred heads in each layer.** Every one of those heads learns.", "sub": ["If the predicted next word is wrong, every head in every layer adjusts its weights using backpropagation (the method that calculates how much each weight contributed to the error). This makes the next prediction closer to the right word."], "ref": "Lecture 18 · p3 · Lecture 19 · p3", "media": {"image": "assets/slides/lecture18/003.webp", "caption": "Lecture 18 · p3"}}], "questions": [{"source": "His question 2", "q": "What are heads, and how do they relate to layers?", "a": "A head is one expert, which is a set of weights that gives its own opinion on how to improve the vectors. Heads sit side by side inside each layer. The layer combines all of its heads' opinions into improved vectors. The layers come one after another from the input to the output. So each layer uses its heads to improve the vectors again."}, {"source": "Predicted (Lectures 17–18) 15", "q": "In the classroom of experts, what are the classes and what are the students?", "a": "In the classroom of experts, the classes are the layers and the students are the heads. This is because you visit the classes one after another, just as the layers come one after another. The students in each class each give a separate opinion at the same time, just as the heads in one layer work side by side. You combine those opinions before moving on to the next class. So each class is one layer, and each student in it is one head."}, {"source": "Predicted (Lectures 17–18) 16", "q": "Which gives an LLM depth and which gives it width, heads or layers?", "a": "Layers give an LLM depth, and heads give it width. This is because layers are rounds of improvement that come one after another, which adds depth. Heads work side by side inside the same layer, which adds width. So more layers means more rounds, and more heads means more experts in each round."}, {"source": "Predicted (Lectures 17–18) 17", "q": "An LLM has 5 layers with 4 heads in each layer. How many heads does it have, and which of them work at the same time?", "a": "The LLM has 20 heads, and the 4 heads inside the same layer work at the same time. This is because each of the 5 layers has 4 heads, and 5 times 4 is 20. The 4 heads inside one layer work side by side. The layers come one after another, so layer 2 works on the vectors that layer 1 improved. So heads in the same layer work at the same time, but heads in different layers do not."}, {"source": "Predicted (Lectures 17–18) 18", "q": "The LLM predicts bark instead of barks after \"the dog that my parents ... \". Which weights change?", "a": "When the LLM predicts bark instead of barks, the weights of every head in every layer change. This is because backpropagation calculates how much each weight contributed to the wrong prediction. Then each weight is adjusted a little in the direction that reduces the error. So the next prediction is closer to barks."}, {"source": "Predicted (Lectures 17–18) 19", "q": "Where is the knowledge of an LLM stored?", "a": "The knowledge of an LLM is stored in its weights. This is because each head is a set of weights, and those weights are what change when the model learns. So the knowledge is spread across all the heads in all the layers. The vowel network's knowledge is stored in its weights in the same way."}]}, {"id": "m3-recurrent-dynamical", "tier": "Kept for the final", "lectures": "Lectures 17 and 18 · repeated in Lecture 19", "title": "The LLM as a dynamical system", "note": "", "blocks": [{"main": "**A dynamical system is a rule that is given its own output as input again and again.** Numbers go in, the rule changes them, and new numbers come out. The output then becomes the next input.", "sub": ["In the **harmonic oscillator** (a mass on a spring moving back and forth), the two numbers are position and velocity (speed and direction). They take turns updating.", "When the rule is repeated step by step, the position traces out a **cosine** shape."], "ref": "Lecture 18 · p4 · Lecture 19 · p4", "media": {"image": "assets/slides/lecture18/004.webp", "caption": "Lecture 18 · p4"}}, {"main": "**An LLM (large language model) can be treated as a dynamical system.** Each layer is the rule, and the depth of the layers plays the role of time. The input vectors are the **initial conditions** (the starting numbers).", "sub": ["Each layer turns the vectors into better vectors, until the last layer can predict the next word.", "Each layer has its own learned weights. So each step passes its output to the next step, but each step uses different weights."], "end": "So in both systems, the output of one step is the input to the next step.", "ref": "Lecture 18 · p4 · Lecture 19 · p4", "media": {"image": "assets/slides/lecture18/004.webp", "caption": "Lecture 18 · p4"}}], "questions": [{"source": "Predicted (Lectures 17–18) 20", "q": "Why is an LLM called a dynamical system?", "a": "An LLM is called a dynamical system because it works by giving a rule its own output again and again. A dynamical system is a rule that is repeatedly given its own output as input, starting from initial conditions (the starting numbers). In an LLM, the input vectors are the initial conditions. Each layer applies its weights to turn those vectors into better vectors, and the next layer takes those as its input. So the depth of the layers plays the role of time."}, {"source": "Predicted (Lectures 17–18) 21", "q": "In the harmonic oscillator, which two numbers update, and in what order?", "a": "In the harmonic oscillator, position x and velocity v update, and they take turns. First, the new x is calculated from the old v. Then, the new v is calculated from the new x. When these two steps are repeated over and over, x traces out a cosine shape."}]}, {"id": "m3-phonotactics", "tier": "Kept for the final", "lectures": "Lectures 17 and 18 · repeated in Lecture 19", "title": "Phonotactics and guessing the next letter", "note": "", "blocks": [{"main": "**Phonotactics are the rules for which sounds can follow which in a language.** Every speaker knows them without being taught. A simple English syllable is a consonant, a vowel and a consonant, as in **Don** or **cup**.", "sub": ["Mat, sit, dog, fish and shave are also consonant, vowel, consonant.", "The pattern is about sounds, not letters. So the silent e at the end of shave does not count, because it makes no sound.", "Ship, chin and bath also count. This is because sh, ch and th are each one sound, even though each is spelled with two letters."], "ref": "Lecture 17 · p6 · Lecture 18 · p6 · Lecture 19 · p6", "media": {"image": "assets/slides/lecture17/006.webp", "caption": "Lecture 17 · p6"}}, {"main": "**Consonants can also form clusters (groups of consonants in a row) before or after the vowel.** A cluster before the vowel is an **onset**, as in split, flat, black and glad. A cluster after the vowel is a **coda**, as in desk, help, milk and lamp.", "sub": ["The order of the consonants is a mirror image around the vowel. For example, l sits right next to the vowel in both flat and help. So flat is a word, and lfat is impossible.", "Each real word has an impossible version that puts the wrong consonant next to the vowel, such as help and hepl, or lamp and lapm.", "Sblit and desb are impossible too. That is why a product called desb would sound un-English."], "ref": "Lecture 17 · p6 · Lecture 18 · p6 · Lecture 19 · p6", "media": {"image": "assets/slides/lecture17/006.webp", "caption": "Lecture 17 · p6"}}, {"main": "**A pair of consonants can be fine across a syllable break but impossible at the start of a syllable.** Atlantic is a word because t and l are on opposite sides of a syllable break (At-lan-tic). Tlantic is impossible because tl cannot start an English syllable.", "sub": ["The sound ng can end a syllable, but it can never start one."], "ref": "Lecture 17 · p6 · Lecture 18 · p6 · Lecture 19 · p6", "media": {"image": "assets/slides/lecture17/006.webp", "caption": "Lecture 17 · p6"}}, {"main": "**Each language has its own phonotactics.** Mandarin allows only nasal sounds (sounds made with air going out through the nose, like n and ng) at the end of a syllable. Russian and Polish allow clusters like zb or dl at the start of a word.", "sub": ["Spanish speakers add an e before st at the start of a word, as in estadio."], "ref": "Lecture 17 · p6 · Lecture 18 · p6 · Lecture 19 · p6", "media": {"image": "assets/slides/lecture17/006.webp", "caption": "Lecture 17 · p6"}}, {"main": "**Guessing the next letter of a word depends on phonotactics, and each guess is a probability distribution.** After a vowel, almost any letter can come next, so the distribution is **flat** (the probability is spread out over many letters). At the start of a word, the choices narrow down to what an English onset allows.", "sub": ["After ra, almost any letter can come next, such as t, n, r or l, so the distribution is flat.", "After skr, the distribution is **sharply peaked** (most of the probability goes to a few vowels)."], "end": "So a GPT trained only on this guessing game learns English syllable structure. This is because guessing the next letter is the same task as an LLM predicting the sixteenth item from the first fifteen.", "ref": "Lecture 17 · p7 · Lecture 18 · p7 · Lecture 19 · p7", "media": {"image": "assets/slides/lecture17/007.webp", "caption": "Lecture 17 · p7"}}, {"main": "**At the start of a word, each first letter or cluster allows only a few next letters.** After sp, only l, r or a vowel can come next, never n. After k, a vowel or n can come next, as in knee, but never t.", "sub": ["After b or f, only r, l or a vowel can come next, never n.", "After sh, only a vowel or r can come next, as in shrimp.", "After skr, or after m at the start of a word, only a vowel can come next."], "ref": "Lecture 17 · p7 · Lecture 18 · p7 · Lecture 19 · p7", "media": {"image": "assets/slides/lecture17/007.webp", "caption": "Lecture 17 · p7"}}, {"main": "**Inside a word, the letters so far can make one next letter almost certain.** After bram, the next letter is almost certainly b, as in bramble.", "sub": ["A new syllable could also start there, so b is not the only possible next letter."], "ref": "Lecture 17 · p7 · Lecture 18 · p7 · Lecture 19 · p7", "media": {"image": "assets/slides/lecture17/007.webp", "caption": "Lecture 17 · p7"}}, {"main": "**After pl, st and th at the start of a word, the next letter is limited too.** After pl, only a vowel can come next, as in play. After st, a vowel or r can come next, as in star and street, but not l or k.", "sub": ["After th, r, w or a vowel can come next, as in three, thwart and thin, but not l or n."], "ref": "Lecture 17 · p7 · Lecture 18 · p7 · Lecture 19 · p7", "media": {"image": "assets/slides/lecture17/007.webp", "caption": "Lecture 17 · p7"}}], "questions": [{"source": "His question 3", "q": "Which could be English words: blick, bnick, sblat, splat, dlag, lisk, lisb, lapm, lamp? For each one that could not, name the problem.", "a": "Blick, splat, lisk and lamp could be English words.\n\nBnick, sblat and dlag could not be English words. This is because bn, sb and dl cannot start a syllable in English.\n\nLisb and lapm could not be English words. This is because sb and pm cannot end a syllable in English."}, {"source": "His question 4", "q": "Each of these starts an English word: pl_, st_ and th_. What could come next, and what could not?", "a": "After pl, only a vowel can come next, as in play. So a consonant such as n cannot come next.\n\nAfter st, a vowel or r can come next, as in star and street. But l and k cannot come next.\n\nAfter th, r, w or a vowel can come next, as in three, thwart and thin. But l and n cannot come next."}, {"source": "Predicted (Lectures 17–18) 22", "q": "After which start is the next-letter distribution flatter, ra_ or skr_? Why?", "a": "The next-letter distribution is flatter after ra than after skr. This is because ra ends in a vowel, and after a vowel almost any letter can come next. So the probability is spread out over many letters. After skr, only a vowel can come next. So most of the probability goes to a few vowels, and the distribution is sharply peaked."}, {"source": "Predicted (Lectures 17–18) 23", "q": "Why is Atlantic an English word but tlantic impossible?", "a": "Atlantic is an English word, but tlantic is impossible. This is because in Atlantic, the t and l are on opposite sides of a syllable break (At-lan-tic), so each syllable follows the rules. In tlantic, tl would have to start a syllable. English does not allow tl at the start of a syllable, so tlantic is impossible."}, {"source": "Predicted (Lectures 17–18) 24", "q": "Could ngop be an English word? Could flim?", "a": "Ngop could not be an English word. This is because the sound ng can end a syllable, as in ring, but it can never start one.\n\nFlim could be an English word. This is because fl is an allowed onset (the consonants before the vowel), as in flat, and im is an allowed ending."}, {"source": "Predicted (Lectures 17–18) 25", "q": "Why does a GPT trained only to guess the next letter end up knowing English syllable structure?", "a": "A GPT trained only to guess the next letter ends up knowing English syllable structure because the patterns of English syllables determine which letters can come next. This is because its guesses can only get better by matching those patterns. So as it learns, its probability distributions take on the shape of those patterns. They are flat after a vowel and sharply peaked after a start such as skr."}, {"source": "Predicted (Lectures 17–18) 26", "q": "Which letter cannot come next after sp_ at the start of a word: l, r, n or a?", "a": "N cannot come next after sp at the start of a word. This is because spn is not an allowed English onset (the consonants before the vowel). After sp, only l, r or a vowel can come next, as in split, spring and spa."}, {"source": "Predicted (Lectures 17–18) 27", "q": "Which letter cannot come next after k_ at the start of a word: a, n or t?", "a": "T cannot come next after k at the start of a word. This is because kt cannot start an English syllable. After k, a vowel or n can come next, as in knee."}, {"source": "Predicted (Lectures 17–18) 28", "q": "What can come next after b_ or f_ at the start of a word, and what cannot?", "a": "After b or f at the start of a word, only r, l or a vowel can come next, as in bring, black, frog and flat. N cannot come next. This is because bn and fn cannot start an English syllable."}, {"source": "Predicted (Lectures 17–18) 29", "q": "What can come next after sh_ at the start of a word?", "a": "After sh at the start of a word, only a vowel or r can come next, as in ship and shrimp. This is because shr is the only consonant cluster that English allows starting with sh."}, {"source": "Predicted (Lectures 17–18) 30", "q": "What can come next after skr_?", "a": "After skr, only a vowel can come next, as in scream and scrap (where the skr sound is spelled scr). This is because skr already fills the whole onset (the consonants before the vowel). So no other consonant can be added before the vowel."}, {"source": "Predicted (Lectures 17–18) 31", "q": "Why are lfat, hepl and lapm impossible when flat, help and lamp are words?", "a": "Lfat, hepl and lapm are impossible because the order of a cluster is a mirror image around the vowel. In flat and help, the l sits right next to the vowel. In lamp, the m sits right next to the vowel. Each impossible version puts the wrong consonant next to the vowel. So it breaks the mirror order, and it cannot be an English word."}, {"source": "Predicted (Lectures 17–18) 32", "q": "Is ship a consonant, vowel, consonant word even though it has four letters?", "a": "Yes, ship is a consonant, vowel, consonant word even though it has four letters. This is because the pattern is about sounds, not letters, and sh is one sound. So ship is the consonant sh, the vowel i and the consonant p."}]}, {"id": "m3-agentic", "tier": "Kept for the final", "lectures": "Lectures 17 and 18 · repeated in Lecture 19", "title": "Agentic systems and Software 3.0", "note": "", "blocks": [{"main": "**An agentic system is a group of LLMs (large language models) connected so that one LLM's output becomes the next LLM's input.** In AI today, an **agent** is just an LLM. In one example, an outline LLM plans the answer, and a writing LLM writes it.", "sub": ["A critic LLM checks the draft, and a revision LLM works back and forth with the critic.", "A final LLM produces the answer that the user sees."], "ref": "Lecture 17 · p4 · Lecture 18 · p2 · Lecture 19 · p2", "media": {"image": "assets/slides/lecture17/004.webp", "caption": "Lecture 17 · p4"}}, {"main": "**The critic loop sends the draft back and forth between the critic and the reviser.** The loop continues until the critic is satisfied or a limit is reached. This loop greatly reduced **hallucination** (when an LLM makes up false statements).", "sub": ["Once each LLM is trained, its weights usually do not change.", "The agents share a common memory, where they write and read information."], "ref": "Lecture 17 · p4 · Lecture 18 · p2 · Lecture 19 · p2", "media": {"image": "assets/slides/lecture17/004.webp", "caption": "Lecture 17 · p4"}}, {"main": "**Software 1.0, 2.0 and 3.0 are three ways to build a program.** **Software 1.0** is writing a program in a programming language such as Python. **Software 2.0** is training a neural network on input and output data, so the program is the network's weights.", "sub": ["**Software 3.0** is having an agentic system build and run the program from instructions written in plain English.", "Building a program this way is called **vibe coding**."], "ref": "Lecture 18 · p8 · Lecture 19 · p8", "media": {"image": "assets/slides/lecture18/008.webp", "caption": "Lecture 18 · p8"}}], "questions": [{"source": "His question 5", "q": "What is an agentic system, in terms of LLMs? Describe the example system.", "a": "An agentic system is a graph (a set of connected parts) of LLMs (large language models), each with its own job. The LLMs are connected so that one LLM's output becomes the next LLM's input.\n\nIn the example system, one LLM outlines, one writes, one critiques, one revises and one produces the final version. The critic and the reviser form a loop. So the draft keeps going back until the critic is satisfied or the limit is reached."}, {"source": "His question 6", "q": "What does the critic loop do, and what does it prevent that was common in earlier LLMs?", "a": "The critic loop sends the draft back and forth between the critic and the reviser until the critic is satisfied. The critic checks each draft, and the reviser fixes the errors the critic finds. So errors are caught and fixed before the answer is shown to the user.\n\nThe critic loop prevents hallucination (when an LLM makes up false statements), which was a common problem in earlier LLMs."}, {"source": "Predicted (Lectures 17–18) 33", "q": "What would happen if the critic LLM were removed?", "a": "If the critic LLM were removed, the draft would go straight from writing to the final answer without being checked. This is because the critic is the LLM that checks the draft. So more made-up statements would reach the user. The critic loop is what greatly reduced hallucination, so without it that reduction would be lost."}, {"source": "Predicted (Lectures 17–18) 34", "q": "What is the difference between Software 2.0 and Software 3.0?", "a": "The difference between Software 2.0 and Software 3.0 is how the program gets built.\n\nIn Software 2.0, a neural network is trained on input and output data, so the program is the network's weights.\n\nIn Software 3.0, an agentic system builds and runs the program from plain English instructions. Building a program this way is called vibe coding."}]}, {"id": "m3-hidden-word", "tier": "New on November 17", "lectures": "Lecture 19", "title": "What an LLM learns: guessing a hidden word", "note": "", "blocks": [{"ref": "Lecture 19 · p9", "main": "**An LLM (large language model) learns by guessing a hidden word and then changing its weights a little.** In the sentence \"The chef cracks the,\" the last word is hidden. The model reads the four words before the gap. Then it has to predict the word that fills the gap.", "sub": ["Each word before the gap gives a clue about the hidden word. These clue relationships are called **interdependencies** (one part of a sequence helps predict another part).", "The model does not know the answer, so it spreads its bets. A bet is the probability the model gives to one word. It bets the most on \"egg,\" less on \"nut\" and the least on \"code.\"", "**Learning means nudging the weights (changing each weight a little) so that these guesses get better.** After the true word is revealed, the weights change a little. Because of that change, the right word gets a bigger bet next time."], "end": "The same idea holds when the signal (the sequence the model reads) contains words, sounds and images. The model still guesses a hidden piece and nudges its weights, so the way it learns stays the same.", "media": {"image": "assets/slides/lecture19/009.webp", "caption": "Lecture 19 · p9"}}], "questions": [{"source": "Predicted (Lecture 19) 1", "q": "How does an LLM learn from the sentence \"The chef cracks the ?\"", "a": "An LLM learns from this sentence by guessing the hidden last word and then changing its weights a little.\n\nThis is because each word before the gap gives a clue about the hidden word. So the model bets the most on \"egg,\" less on \"nut\" and the least on \"code.\" When the true word is revealed, the weights are nudged. So the right word gets a bigger bet next time."}, {"source": "Predicted (Lecture 19) 2", "q": "Why does the model give \"egg,\" \"nut\" and \"code\" different bets instead of one answer?", "a": "The model gives three different bets because it does not know the hidden word. All three words could follow \"The chef cracks the.\" The words before the gap make \"egg\" the most likely. So \"egg\" gets the largest bet, \"nut\" gets a smaller bet and \"code\" gets the smallest bet."}, {"source": "Predicted (Lecture 19) 3", "q": "What does learning change in an LLM, and in which direction?", "a": "Learning changes the weights. Each weight is nudged, which means it changes a little. The weights change in the direction that gives the right word a bigger bet the next time."}]}, {"id": "m3-conversion", "tier": "New on November 17", "lectures": "Lecture 19", "title": "Turning speech and images into rows of vectors", "note": "", "blocks": [{"ref": "Lecture 19 · p10", "main": "**An LLM can only read a row of vectors (lists of numbers), so speech and images have to be converted first.** Text, speech and images arrive in three different forms.", "sub": ["**Text** is already a row of pieces, such as \"Now,\" \"crack,\" \"the\" and \"egg,\" and each piece can become one vector.", "**Speech** is air pressure changing in time, and there are no words in the sound itself.", "An **image** is a grid of light, and it contains no words either."], "end": "So the first job is a conversion. Speech and images both have to become rows of vectors, because that is all the LLM can read.", "media": {"image": "assets/slides/lecture19/010.webp", "caption": "Lecture 19 · p10"}}, {"ref": "Lecture 19 · p11", "main": "**Speech is turned into a row of vectors by slicing it in time.** The sound is cut into short slices, and each slice is called a **frame**. Each slice is about 20 milliseconds long.", "sub": ["The slices go through a **speech encoder** (a neural network that was trained on a large amount of audio). One vector comes out for each slice.", "**One second of speech becomes 50 vectors.** This is because each slice is about 20 milliseconds long, and 50 slices of that length fill one second. Each slice gives one vector.", "The vectors stay in time order. The first slice gives the first vector, and the last slice gives the last vector."], "end": "So speech is now a row, just like a sentence, and the LLM can read it one vector after another.", "media": {"image": "assets/slides/lecture19/011.webp", "caption": "Lecture 19 · p11"}}, {"ref": "Lecture 19 · p12", "main": "**An image is turned into a row of vectors by cutting it into patches.** A **patch** is one small square of the image. A grid cuts the image of an egg in a pan into 16 patches.", "sub": ["The patches are laid out in a row in **reading order** (left to right along the top, then left to right along the next line down). This turns the image into a sequence, like a sentence.", "The patches go through a **vision encoder**. One vector comes out for each patch, so 16 patches give 16 vectors.", "Real systems use much smaller patches of 14 to 16 pixels. Smaller patches mean more patches for the same image, so one image gives hundreds of vectors."], "end": "So both conversions follow the same steps. The signal is cut into small pieces, the pieces are kept in order, and an encoder gives one vector for each piece.", "media": {"image": "assets/slides/lecture19/012.webp", "caption": "Lecture 19 · p12"}}], "questions": [{"source": "Predicted (Lecture 19) 4", "q": "Why is text easier for an LLM to read than speech or an image?", "a": "Text is easier because it is already a row of pieces. Each piece, such as \"Now,\" \"crack,\" \"the\" or \"egg,\" can become one vector.\n\nSpeech is air pressure changing in time, and an image is a grid of light. Neither one contains words or separate pieces. So both have to be converted into rows of vectors first."}, {"source": "Predicted (Lecture 19) 5", "q": "How is speech turned into a row of vectors?", "a": "Speech is turned into a row of vectors by slicing it in time. First, the sound is cut into short slices called frames, each about 20 milliseconds long. Then the slices go through a speech encoder, which is a neural network trained on a large amount of audio. One vector comes out for each slice, and the vectors stay in time order."}, {"source": "Predicted (Lecture 19) 6", "q": "Why does one second of speech become 50 vectors?", "a": "One second of speech becomes 50 vectors because each slice gives one vector. Each slice is about 20 milliseconds long, and 50 slices of that length fill one second. So one second gives 50 vectors."}, {"source": "Predicted (Lecture 19) 7", "q": "How is an image turned into a row of vectors?", "a": "An image is turned into a row of vectors by cutting it into patches. First, a grid cuts the image into small squares called patches. Then the patches are laid out in a row in reading order, so the image becomes a sequence. Last, a vision encoder gives one vector for each patch."}, {"source": "Predicted (Lecture 19) 8", "q": "The egg example gives 16 vectors. Why does one image give hundreds of vectors in real systems?", "a": "One image gives hundreds of vectors in real systems because real systems use much smaller patches. Their patches are only 14 to 16 pixels. Smaller patches mean more patches for the same image. Each patch gives one vector, so there are hundreds of vectors."}, {"source": "Predicted (Lecture 19) 9", "q": "What is the similarity between converting speech and converting an image, and what is the difference?", "a": "The similarity is that both are cut into small pieces, the pieces are kept in order, and an encoder gives one vector for each piece.\n\nThe difference is what is cut. Speech is cut in time into frames of about 20 milliseconds. An image is cut in space into square patches, which are then placed in reading order."}]}, {"id": "m3-one-row", "tier": "New on November 17", "lectures": "Lecture 19", "title": "One row, three senses: cross-modal dependencies", "note": "", "blocks": [{"ref": "Lecture 19 · p13", "main": "**Image patches, speech frames and words can all be placed in one row, and the model guesses the hidden piece.** The image patches come first, the speech frames come next, and the words come last. The words are \"Now,\" \"crack\" and \"the,\" and the word after them is hidden.", "sub": ["The words before the gap still give clues, the same as in a row that holds only text.", "Clues now also come from the other senses. A patch that contains an egg helps the model guess the hidden word. The sound of cracking helps too.", "A link between two different kinds of signal is called a **cross-modal dependency**."], "end": "So the game is exactly the same as before. The only new thing is that some of the clues come from other senses.", "media": {"image": "assets/slides/lecture19/013.webp", "caption": "Lecture 19 · p13"}}, {"ref": "Lecture 19 · p14", "main": "**\"Three cute puppies\" is one event given in three forms, and training puts all three in one row.** The first form is an image of three puppies, cut into 18 patches. The second form is the phrase spoken aloud. The third form is the three written words.", "sub": ["The spoken phrase is shown as a **spectrogram** (a display of a sound laid out in time). Time runs from left to right. Higher up means a higher frequency. A darker area means more energy.", "Each thin column of the spectrogram is one frame. Each word has its own stretch of time, with \"three\" first and \"puppies\" last.", "The voice is a speech synthesizer (an MBROLA diphone voice). It is not a recording of a person."], "end": "So the image, the sound and the words are three views of one event. In training, one piece of the row is hidden, and the model has to guess it.", "media": {"image": "assets/slides/lecture19/014.webp", "caption": "Lecture 19 · p14"}}], "questions": [{"source": "Predicted (Lecture 19) 10", "q": "What is a cross-modal dependency? Give an example.", "a": "A cross-modal dependency is a link between two different kinds of signal, in which a piece from one sense helps predict a piece from another sense.\n\nFor example, in \"Now crack the ?\", an image patch that contains an egg helps the model guess the hidden word. The sound of cracking helps too."}, {"source": "Predicted (Lecture 19) 11", "q": "When image patches and speech frames are added to the row, what stays the same and what changes?", "a": "The game stays the same. The model still guesses the hidden piece from the pieces it can read, and the words before the gap still give clues.\n\nWhat changes is where some of the clues come from. Some clues now come from image patches and speech frames."}, {"source": "Predicted (Lecture 19) 12", "q": "In the spectrogram of \"three cute puppies,\" what do left to right, height and darkness mean?", "a": "Left to right is time, so \"three\" comes first and \"puppies\" comes last. Height is frequency, so higher up means a higher frequency. Darkness is energy, so a darker area means more energy. Each thin column is one frame."}, {"source": "Predicted (Lecture 19) 13", "q": "Why are the image, the spectrogram and the words called three views of one event?", "a": "They are called three views of one event because all three describe the same thing, which is three cute puppies. The image gives it as patches, the speech gives it as frames, and the text gives it as words. In training, all three go into one row."}]}, {"id": "m3-training", "tier": "New on November 17", "lectures": "Lecture 19", "title": "The three training examples: hidden word, hidden sound frame, hidden image patch", "note": "", "blocks": [{"ref": "Lecture 19 · p15", "main": "**In training example 1, the hidden piece is a word, and the image and the sound settle the guess.** The row holds the image, then the sound, then the words \"three\" and \"cute.\" The word after \"cute\" is hidden.", "sub": ["With the words alone, the bets are spread out. This is because many endings fit after \"three cute,\" such as \"kittens,\" \"puppies\" and \"babies.\"", "With the image and the sound, the bet piles up on \"puppies.\" This is because the image contains puppies, and the sound contains the spoken word \"puppies.\"", "The true word is then revealed, and the model is graded on how much it bet on that word. The model bet 0.85 on \"puppies.\""], "end": "So the nudge to the weights is small. This is because the model bet a lot on the true word, so the error is small, and a small error moves the weights only a little.", "media": {"image": "assets/slides/lecture19/015.webp", "caption": "Lecture 19 · p15"}}, {"ref": "Lecture 19 · p16", "main": "**In training example 2, the hidden piece is a frame of sound, and three clues help the model guess it.** The row is put in a new order, with the image first, then the words, then the sound. This is like teaching the model to speak a sentence it was given. The sound is predicted frame by frame, from left to right.", "sub": ["The frames already heard are the first clue. The voice and the **formants** (frequency regions with strong energy) change smoothly, so the last few frames say a lot about the next one.", "The words are the second clue. They say which sound should come next, and here it is the vowel in \"pup.\"", "The image is the third clue. It contains puppies, so it backs up the words. It is a weaker clue here.", "A frame is a column of numbers. Each number is how much energy there is in one frequency band. The guess is close to the true frame, but it is not exact."], "end": "So the error is how far each guessed number is from the true number, and that error nudges the weights.", "media": {"image": "assets/slides/lecture19/016.webp", "caption": "Lecture 19 · p16"}}, {"ref": "Lecture 19 · p17", "main": "**In training example 3, the hidden piece is a patch of the image, and the biggest error is the colour.** The row is put in a new order again, with the words first, then the sound, then the image. This is like teaching the model to draw what it was told. The patches are predicted in reading order.", "sub": ["The patches already drawn are the first clue. Above the hidden patch is background. To its left are two puppies, so the model has seen what a puppy in this image looks like.", "The words are the second clue. \"Three\" says a third puppy must appear, because only two are drawn. \"Puppies\" says to expect dog ears.", "The sound is the third clue. It carries the same words, so it backs up the text.", "The model guesses a blurry puppy ear in the average colour of the first two puppies. The true puppy is dark."], "end": "So the biggest error is the colour. This is because no clue in the words, the sound or the patches already drawn said the third puppy would be dark. Only systems that also produce images are trained this way.", "media": {"image": "assets/slides/lecture19/017.webp", "caption": "Lecture 19 · p17"}}], "questions": [{"source": "Predicted (Lecture 19) 14", "q": "How do the model's bets on the next word change when the image and the sound are added to \"three cute\"?", "a": "With the words alone, the bets are spread out over \"kittens,\" \"puppies\" and \"babies.\" This is because many endings fit after \"three cute.\"\n\nWith the image and the sound, the bet piles up on \"puppies.\" This is because the image contains puppies, and the sound contains the spoken word \"puppies.\""}, {"source": "Predicted (Lecture 19) 15", "q": "The model bet 0.85 on \"puppies,\" and the true word is \"puppies.\" Is the nudge to the weights large or small? Why?", "a": "The nudge to the weights is small. This is because the model is graded on how much it bet on the true word. It bet 0.85, which is a lot, so the error is small. A small error moves the weights only a little."}, {"source": "Predicted (Lecture 19) 16", "q": "What would happen to the nudge if the model had bet only a little on \"puppies\"?", "a": "The nudge would be larger. This is because a small bet on the true word is a large error. A larger error moves the weights more, so that the true word gets a bigger bet next time."}, {"source": "Predicted (Lecture 19) 17", "q": "Name the three clues that help the model predict a hidden sound frame, and say what each one gives.", "a": "The first clue is the frames already heard. The voice and the formants change smoothly, so the last few frames say a lot about the next one.\n\nThe second clue is the words. They say which sound should come next, which here is the vowel in \"pup.\"\n\nThe third clue is the image. It contains puppies, so it backs up the words, but it is a weaker clue here."}, {"source": "Predicted (Lecture 19) 18", "q": "What is the error when the model guesses a sound frame?", "a": "The error is how far the guess is from the true frame. A frame is a column of numbers, and each number is how much energy there is in one frequency band. The error is how far apart each guessed number is from the matching true number. That error nudges the weights."}, {"source": "Predicted (Lecture 19) 19", "q": "In training example 3, why is the colour the biggest error?", "a": "The colour is the biggest error because no clue gave the colour of the third puppy. The model guessed a puppy ear in the average colour of the first two puppies. The true puppy is dark. Nothing in the words, the sound or the patches already drawn said the third puppy would be dark."}, {"source": "Predicted (Lecture 19) 20", "q": "What do the words \"three\" and \"puppies\" tell the model about the hidden image patch?", "a": "\"Three\" tells the model that a third puppy must appear, because only two puppies have been drawn so far. \"Puppies\" tells the model to expect dog ears. So the model guesses a puppy ear for the hidden patch."}, {"source": "Predicted (Lecture 19) 21", "q": "Are all systems trained to predict image patches?", "a": "No. Only systems that also produce images are trained to predict image patches. Systems that only read images usually skip this step. This is because predicting a patch is like teaching the model to draw what it was told."}]}, {"id": "m3-clues", "tier": "New on November 17", "lectures": "Lecture 19", "title": "Every piece can be the hidden one: two kinds of clue", "note": "", "blocks": [{"ref": "Lecture 19 · p18", "main": "**Any piece of the row can be the hidden one, and each sense gives a clue for it.** The hidden piece can be a word, a sound frame or an image patch.", "sub": ["For a **hidden word**, the words \"three cute\" call for a plural noun, the sound has just spoken the word, and the image contains puppies.", "For a **hidden frame**, the words say which sound comes next, the voice and the formants carry on, and the image backs up which word is being said.", "For a **hidden patch**, the word \"three\" says one more puppy is coming, the sound gives the same words in heard form, and the fur and the background carry on."], "end": "So a clue from the same sense says how the signal continues, and clues from the other senses say what the thing is. Training on all three senses together helps, because each sense fills gaps that the others leave.", "media": {"image": "assets/slides/lecture19/018.webp", "caption": "Lecture 19 · p18"}}], "questions": [{"source": "Predicted (Lecture 19) 22", "q": "What is the difference between a clue from the same sense as the hidden piece and a clue from another sense?", "a": "A clue from the same sense mostly says how the signal continues. Grammar does this for a hidden word, smooth formants do it for a hidden frame, and fur and background do it for a hidden patch.\n\nClues from the other senses mostly say what the thing is. Here they say puppies, three of them."}, {"source": "Predicted (Lecture 19) 23", "q": "For a hidden sound frame, which clue comes from the same sense, and what does it tell the model?", "a": "The clue from the same sense is that the voice and the formants carry on from the frames already heard. It tells the model how the sound continues. The words and the image are the other senses, and they say which word is being said."}, {"source": "Predicted (Lecture 19) 24", "q": "Why does training on words, sound and images together help?", "a": "Training on all three senses together helps because each sense fills gaps that the others leave. A clue from the same sense says how the signal continues. Clues from the other senses say what the thing is. So with all three senses, the model has both kinds of clue for every hidden piece."}]}, {"id": "m3-talking-back", "tier": "New on November 17", "lectures": "Lecture 19", "title": "Talking back, what is new and what stays the same", "note": "", "blocks": [{"ref": "Lecture 19 · p19", "main": "**The model speaks by predicting codes for sound, and a decoder turns the codes back into sound.** First, sound is compressed into discrete codes (separate numbered units), such as 417, 82 and 903. Each code works like a new word added to the vocabulary.", "sub": ["The model predicts the next code exactly as it predicts the next word. So speaking is the same guessing game again.", "A **decoder** then turns the row of predicted codes back into a sound wave that can be heard."], "end": "So the model gives the codes, and the decoder gives the sound.", "media": {"image": "assets/slides/lecture19/019.webp", "caption": "Lecture 19 · p19"}}, {"ref": "Lecture 19 · p19", "main": "**Three things are new when a model is trained on words, sounds and images, and one thing stays the same.** The first new thing is a **shared currency**, in which everything becomes vectors in one row. The second is **data where the senses appear together**. The third is **a schedule that protects what was already learned**.", "sub": ["What stays the same is the learning rule, which is to find the dependencies in the signal."], "end": "So the model still guesses a hidden piece and nudges its weights. The signal has only become wider, because it now holds words, sounds and images.", "media": {"image": "assets/slides/lecture19/019.webp", "caption": "Lecture 19 · p19"}}], "questions": [{"source": "Predicted (Lecture 19) 25", "q": "How does the model talk back?", "a": "The model talks back by predicting codes for sound. First, sound is compressed into discrete codes, and each code works like a new word in the vocabulary. Then the model predicts the next code exactly as it predicts the next word. Last, a decoder turns the codes back into a sound wave."}, {"source": "Predicted (Lecture 19) 26", "q": "What three things are new when an LLM is trained on words, sounds and images?", "a": "The first new thing is a shared currency, in which everything becomes vectors in one row. The second is data where the senses appear together. The third is a schedule that protects what was already learned."}, {"source": "Predicted (Lecture 19) 27", "q": "What stays the same when the signal holds words, sounds and images?", "a": "The learning rule stays the same. The model still finds the dependencies in the signal by guessing a hidden piece and nudging its weights. The signal has only become wider."}]}]}}, "bytopic": {"title": "Notes by topic · Lectures 17–19", "lead": "Each topic brings together every slide that teaches it, from Lectures 17, 18 and 19, said once. Read the notes with their slide beside them, then answer the questions.", "topics": [{"id": "m3-lead-up", "title": "Leading up to LLMs: from one neuron to networks that unfold over time", "lectures": "Lecture 17 (start) and Lecture 18", "blocks": [{"main": "**A neuron in an artificial neural network takes in a vector (a list of numbers) and gives back one number.** It multiplies each input by its weight and adds the results. This is called the **inner product**. A **neural network** repeats the inner product layer after layer.", "sub": ["A neural network takes in one vector and gives back a vector of decisions."], "ref": "Lecture 17 · p2", "media": {"image": "assets/slides/lecture17/002.webp", "caption": "Lecture 17 · p2"}}, {"main": "**Artificial neural networks began in biology, not in technology.** The first paper on artificial neural networks was by **McCulloch and Pitts**. It started from the all-or-none behavior of real neurons. A real neuron is either firing or not firing. This is the same idea as the **sigmoid** (a function that turns a number into a value between 0 and 1).", "sub": ["The earliest neural network work tried to model how the mind works, including mental illness.", "In the **Parallel Distributed Processing** books, **parallel** means many neurons calculate their activations at the same time.", "**Distributed** means the information from the inputs is spread across all the neurons. By the time these books were written, forward propagation and backpropagation were well worked out."], "ref": "Lecture 17 · p2", "media": {"image": "assets/slides/lecture17/002.webp", "caption": "Lecture 17 · p2"}}, {"main": "**The vowel network takes one static vector and makes one decision.** A **static** vector is a fixed list of numbers from one moment in time. But speech changes all the time, and a sentence is many words, one after another.", "sub": ["So one fixed list of numbers cannot model thinking that unfolds over time."], "ref": "Lecture 17 · p2", "media": {"image": "assets/slides/lecture17/002.webp", "caption": "Lecture 17 · p2"}}, {"main": "**A recurrent network sends its own output back into part of its input, so what it produces at one moment helps predict the next moment.** **Michael Jordan** built the **recurrent** network to model speech production. He built it because features such as nasality and lip rounding switch on and off at different moments.", "sub": ["**Plan units** hold what the network is supposed to say, and **state units** hold a copy of the last output. Both send their values to the hidden layer, and the hidden layer sends its values to the output.", "The output is copied back into the state units. The same weights are used at every step."], "end": "So a recurrent network can work through a sequence, instead of handling only one static vector.", "ref": "Lecture 17 · p3", "media": {"image": "assets/slides/lecture17/003.webp", "caption": "Lecture 17 · p3"}}, {"main": "**GPT works the same way as the recurrent network, one word at a time.** It predicts the next word and adds that word to the prompt. Then it uses the whole prompt, including the new word, as input to predict the word after that.", "sub": ["The main steps in this history are 1943 (the McCulloch and Pitts paper), 1985 (backpropagation) and 2017 (the design behind GPT)."], "ref": "Lecture 17 · p3", "media": {"image": "assets/slides/lecture17/003.webp", "caption": "Lecture 17 · p3"}}], "questions": [{"source": "Predicted (Lectures 17–18) 1", "q": "How does the all-or-none behavior of neurons connect to the sigmoid?", "a": "The all-or-none behavior of neurons is the same idea as the sigmoid. This is because a real neuron is either firing or not firing. The sigmoid turns an inner product into a number near 0 (off) or near 1 (on), with a steep change in between. So an artificial neuron that uses the sigmoid behaves the same way as a real neuron."}, {"source": "Predicted (Lectures 17–18) 2", "q": "What do parallel and distributed mean in Parallel Distributed Processing?", "a": "Parallel means that many neurons calculate their activations at the same time.\n\nDistributed means that the information from the inputs is spread across all the neurons. So the information is not stored in one place."}, {"source": "Predicted (Lectures 17–18) 3", "q": "What does a single neuron take in and give back? What about a neural network?", "a": "A single neuron takes in a vector and gives back one number. That number is the inner product, which is each input multiplied by its weight, with the results added together.\n\nA neural network takes in one vector and gives back a vector of decisions. This is because a neural network repeats the inner product layer after layer. So the network ends with several outputs instead of just one number."}, {"source": "Predicted (Lectures 17–18) 4", "q": "Why can't the vowel network model a sentence or speech over time?", "a": "The vowel network cannot model a sentence or speech over time because it takes one static vector and makes one decision. That vector is F1 and F2 (the first two formants) from one moment. But speech changes all the time, and a sentence is many words, one after another. So modeling speech needs a network that works through a sequence."}, {"source": "Predicted (Lectures 17–18) 5", "q": "What makes Jordan's network recurrent, and why did he build it?", "a": "Jordan's network is recurrent because it sends its own output back into part of its input. It copies the output into the state units. So what it produced at one moment helps predict the next moment.\n\nJordan built it because speech production changes over time. Features such as nasality and lip rounding switch on and off at different moments. So he needed a network that could follow these changes step by step."}, {"source": "Predicted (Lectures 17–18) 6", "q": "How is a recurrent network different from an nn.Sequential network?", "a": "A recurrent network is different from an nn.Sequential network because it loops its output back into its input. A Sequential network passes the input through the layers once, from the input to the output, and makes one decision. A recurrent network sends its output back in as part of its next input. So a recurrent network works through a sequence step by step."}, {"source": "Predicted (Lectures 17–18) 7", "q": "How does GPT use the same idea as Jordan's network?", "a": "GPT uses the same idea as Jordan's network because it also feeds its own output back into its input. It predicts the next word and adds that word to the prompt. Then it predicts again, using the longer prompt. So GPT produces text one word at a time."}]}, {"id": "m3-llm-sequences", "title": "From the vowel network to an LLM: many vectors in, the next item out", "lectures": "Lectures 17 and 18 · repeated in Lecture 19", "blocks": [{"main": "**An LLM (large language model) is given a sequence of vectors (lists of numbers) and predicts the next one.** For example, it is given 15 vectors and predicts the sixteenth. The sixteenth is a probability distribution (a list of how likely each option is) over what could come next, such as each of about 30,000 English words.", "sub": ["The vectors can be words, frames of a spectrogram (short time slices of a display of a sound's frequencies), patches of an image or the amino acids of a protein.", "The LLM only ever works with lists of numbers, so the same design works for all of them."], "ref": "Lecture 17 · p5 · Lecture 18 · p5 · Lecture 19 · p5", "media": {"image": "assets/slides/lecture17/005.webp", "caption": "Lecture 17 · p5"}}, {"main": "**Language depends on connections between words that are far apart.** In \"the dog that my parents, who I love very much, ...\", the next word is **barks**. Barks goes with the singular word dog, no matter how many words come in between.", "sub": ["An LLM learns this from data, not from a rule someone teaches it."], "ref": "Lecture 17 · p4 · Lecture 18 · p2 · Lecture 19 · p2", "media": {"image": "assets/slides/lecture17/004.webp", "caption": "Lecture 17 · p4"}}, {"main": "**An LLM learns by predicting the next word, such as mat after \"the cat sat on the\".** When the prediction is wrong, backpropagation adjusts the weights. This is repeated with a huge number of sentences.", "sub": ["Underneath everything, **inference** (using the network to make a prediction) is done with inner products. Learning is done with stochastic gradient descent plus **dynamic programming** (reusing calculations already done, which is how backpropagation works backward through the layers).", "An LLM predicts from past data. So when something is not covered by its data, it can make things up, which is called **hallucination**."], "ref": "Lecture 17 · p4 · Lecture 18 · p2 · Lecture 19 · p2", "media": {"image": "assets/slides/lecture17/004.webp", "caption": "Lecture 17 · p4"}}], "questions": [{"source": "His question 1", "q": "What is the difference between the input and output of the vowel network and those of an LLM?", "a": "The difference is that the vowel network takes in one vector and decides among five categories, while an LLM takes in many vectors and decides among a whole vocabulary.\n\nThe vowel network's input is one vector, F1 and F2. Its output decides among five categories.\n\nAn LLM's input is many vectors in sequence, such as the words so far. Its output decides among a whole vocabulary for the next item."}, {"source": "Predicted (Lectures 17–18) 8", "q": "An LLM is given 15 vectors and predicts the sixteenth. Name three things the vectors can stand for.", "a": "Three things the vectors can stand for are the words of a sentence, the frames of a spectrogram and the patches of an image. They can also stand for the amino acids of a protein. The same kind of prediction works for all of them. This is because the LLM only works with lists of numbers, whatever those numbers stand for."}, {"source": "Predicted (Lectures 17–18) 9", "q": "What does the sixteenth vector look like, and does it add up to anything?", "a": "The sixteenth vector is a probability distribution over what could come next, and its numbers add up to one.\n\nThe sixteenth vector has one number for each possible next item, such as each English word. Each number is how likely that item is to come next.\n\nIt adds up to one because it is a probability distribution. The probabilities of all the possible next items always add up to one."}, {"source": "Predicted (Lectures 17–18) 10", "q": "Why is the next word barks and not bark in \"the dog that my parents, who I love very much, ... \"?", "a": "The next word is barks and not bark because barks goes with the singular word dog. This is true no matter how many words come in between. It holds even when the plural word parents comes in between. To predict barks, an LLM has to use a word far back in the sequence. It learns to do this from data, by computing inner products layer after layer."}, {"source": "Predicted (Lectures 17–18) 11", "q": "Why can an LLM hallucinate?", "a": "An LLM can hallucinate because it predicts from past data. When it meets something its data does not cover, its prediction can turn into a guess. So it can make things up, and this is called hallucination."}]}, {"id": "m3-gestalt-cloze", "title": "Gestalt completion and the cloze test", "lectures": "Lecture 17 · repeated in Lecture 19", "blocks": [{"main": "**Gestalt psychology studies how people see whole patterns.** In the Gestalt figure, people see a triangle even though no triangle is drawn. They see it because a large part of human knowledge is completing what is missing.", "sub": ["**Closure** is the Gestalt term for completing a familiar pattern that is not quite finished. For example, people see a broken circle as a whole circle."], "ref": "Lecture 17 · p5 · Lecture 18 · p5 · Lecture 19 · p5", "media": {"image": "assets/slides/lecture17/005.webp", "caption": "Lecture 17 · p5"}}, {"main": "**In a cloze test, words are removed from a text, and people fill them in.** The name cloze comes from closure. The test measures knowledge by asking someone to complete a sequence.", "sub": ["An LLM (large language model) that predicts the next word is doing a cloze test again and again."], "end": "So training a system only to predict the missing piece turns out to copy human thinking.", "ref": "Lecture 17 · p5 · Lecture 18 · p5 · Lecture 19 · p5", "media": {"image": "assets/slides/lecture17/005.webp", "caption": "Lecture 17 · p5"}}], "questions": [{"source": "Predicted (Lectures 17–18) 12", "q": "Describe the Gestalt principle of closure, and how an LLM uses it to learn.", "a": "The Gestalt principle of closure is completing a familiar pattern that is not quite finished. For example, people see a triangle where none is drawn, and they see a broken circle as a whole circle.\n\nAn LLM (large language model) uses closure to learn by doing the same kind of completion. It predicts the missing next piece of a sequence again and again. When its prediction is wrong, it corrects its weights. So it learns by completing sequences over and over."}, {"source": "Predicted (Lectures 17–18) 13", "q": "What is a cloze test, and why is an LLM's training like one?", "a": "A cloze test is a test where words are removed from a text and people fill them in. So it tests knowledge by asking someone to complete a sequence.\n\nAn LLM's training is like a cloze test because the LLM (large language model) is trained by filling in the next word over and over. So for an LLM, knowing something means being able to complete the sequence."}, {"source": "Predicted (Lectures 17–18) 14", "q": "Why do people see a triangle in the Gestalt figure?", "a": "People see a triangle in the Gestalt figure because they complete the missing parts of a familiar pattern. No triangle is actually drawn, but people fill in what is missing. This completion is the Gestalt principle of closure.", "img": "assets/exam2/gen-kanizsa-triangle.svg", "alt": "Three black circles with wedges cut out, facing each other"}]}, {"id": "m3-heads-layers", "title": "Heads and layers", "lectures": "Lecture 18 · repeated in Lecture 19", "blocks": [{"main": "**An LLM (large language model) is built from layers, and each layer contains heads.** A **layer** is one round of improving the vectors (the lists of numbers that represent the words). The layers come one after another from the input to the output. A **head** is one expert, and it is a set of weights. The heads sit side by side inside each layer.", "sub": ["Each head gives its own opinion on how to improve the vectors.", "The layer combines the opinions of all its heads into improved vectors. Then the next layer does the same thing again with those improved vectors."], "ref": "Lecture 18 · p3 · Lecture 19 · p3", "media": {"image": "assets/slides/lecture18/003.webp", "caption": "Lecture 18 · p3"}}, {"main": "**Heads and layers work like visiting a series of classes to improve yourself.** The classes you visit one after another are the **layers**. The students in each class, who each give you an opinion, are the **heads**.", "sub": ["Layers give an LLM **depth**, which means one round of improvement after another.", "Heads give an LLM **width**, which means many experts are asked at the same time in each round."], "ref": "Lecture 18 · p3 · Lecture 19 · p3", "media": {"image": "assets/slides/lecture18/003.webp", "caption": "Lecture 18 · p3"}}, {"main": "**Predicting the next word is so hard that large systems have a hundred or more layers, with about a hundred heads in each layer.** Every one of those heads learns.", "sub": ["If the predicted next word is wrong, every head in every layer adjusts its weights using backpropagation (the method that calculates how much each weight contributed to the error). This makes the next prediction closer to the right word."], "ref": "Lecture 18 · p3 · Lecture 19 · p3", "media": {"image": "assets/slides/lecture18/003.webp", "caption": "Lecture 18 · p3"}}], "questions": [{"source": "His question 2", "q": "What are heads, and how do they relate to layers?", "a": "A head is one expert, which is a set of weights that gives its own opinion on how to improve the vectors. Heads sit side by side inside each layer. The layer combines all of its heads' opinions into improved vectors. The layers come one after another from the input to the output. So each layer uses its heads to improve the vectors again."}, {"source": "Predicted (Lectures 17–18) 15", "q": "In the classroom of experts, what are the classes and what are the students?", "a": "In the classroom of experts, the classes are the layers and the students are the heads. This is because you visit the classes one after another, just as the layers come one after another. The students in each class each give a separate opinion at the same time, just as the heads in one layer work side by side. You combine those opinions before moving on to the next class. So each class is one layer, and each student in it is one head."}, {"source": "Predicted (Lectures 17–18) 16", "q": "Which gives an LLM depth and which gives it width, heads or layers?", "a": "Layers give an LLM depth, and heads give it width. This is because layers are rounds of improvement that come one after another, which adds depth. Heads work side by side inside the same layer, which adds width. So more layers means more rounds, and more heads means more experts in each round."}, {"source": "Predicted (Lectures 17–18) 17", "q": "An LLM has 5 layers with 4 heads in each layer. How many heads does it have, and which of them work at the same time?", "a": "The LLM has 20 heads, and the 4 heads inside the same layer work at the same time. This is because each of the 5 layers has 4 heads, and 5 times 4 is 20. The 4 heads inside one layer work side by side. The layers come one after another, so layer 2 works on the vectors that layer 1 improved. So heads in the same layer work at the same time, but heads in different layers do not."}, {"source": "Predicted (Lectures 17–18) 18", "q": "The LLM predicts bark instead of barks after \"the dog that my parents ... \". Which weights change?", "a": "When the LLM predicts bark instead of barks, the weights of every head in every layer change. This is because backpropagation calculates how much each weight contributed to the wrong prediction. Then each weight is adjusted a little in the direction that reduces the error. So the next prediction is closer to barks."}, {"source": "Predicted (Lectures 17–18) 19", "q": "Where is the knowledge of an LLM stored?", "a": "The knowledge of an LLM is stored in its weights. This is because each head is a set of weights, and those weights are what change when the model learns. So the knowledge is spread across all the heads in all the layers. The vowel network's knowledge is stored in its weights in the same way."}]}, {"id": "m3-recurrent-dynamical", "title": "The LLM as a dynamical system", "lectures": "Lectures 17 and 18 · repeated in Lecture 19", "blocks": [{"main": "**A dynamical system is a rule that is given its own output as input again and again.** Numbers go in, the rule changes them, and new numbers come out. The output then becomes the next input.", "sub": ["In the **harmonic oscillator** (a mass on a spring moving back and forth), the two numbers are position and velocity (speed and direction). They take turns updating.", "When the rule is repeated step by step, the position traces out a **cosine** shape."], "ref": "Lecture 18 · p4 · Lecture 19 · p4", "media": {"image": "assets/slides/lecture18/004.webp", "caption": "Lecture 18 · p4"}}, {"main": "**An LLM (large language model) can be treated as a dynamical system.** Each layer is the rule, and the depth of the layers plays the role of time. The input vectors are the **initial conditions** (the starting numbers).", "sub": ["Each layer turns the vectors into better vectors, until the last layer can predict the next word.", "Each layer has its own learned weights. So each step passes its output to the next step, but each step uses different weights."], "end": "So in both systems, the output of one step is the input to the next step.", "ref": "Lecture 18 · p4 · Lecture 19 · p4", "media": {"image": "assets/slides/lecture18/004.webp", "caption": "Lecture 18 · p4"}}], "questions": [{"source": "Predicted (Lectures 17–18) 20", "q": "Why is an LLM called a dynamical system?", "a": "An LLM is called a dynamical system because it works by giving a rule its own output again and again. A dynamical system is a rule that is repeatedly given its own output as input, starting from initial conditions (the starting numbers). In an LLM, the input vectors are the initial conditions. Each layer applies its weights to turn those vectors into better vectors, and the next layer takes those as its input. So the depth of the layers plays the role of time."}, {"source": "Predicted (Lectures 17–18) 21", "q": "In the harmonic oscillator, which two numbers update, and in what order?", "a": "In the harmonic oscillator, position x and velocity v update, and they take turns. First, the new x is calculated from the old v. Then, the new v is calculated from the new x. When these two steps are repeated over and over, x traces out a cosine shape."}]}, {"id": "m3-phonotactics", "title": "Phonotactics and guessing the next letter", "lectures": "Lectures 17 and 18 · repeated in Lecture 19", "blocks": [{"main": "**Phonotactics are the rules for which sounds can follow which in a language.** Every speaker knows them without being taught. A simple English syllable is a consonant, a vowel and a consonant, as in **Don** or **cup**.", "sub": ["Mat, sit, dog, fish and shave are also consonant, vowel, consonant.", "The pattern is about sounds, not letters. So the silent e at the end of shave does not count, because it makes no sound.", "Ship, chin and bath also count. This is because sh, ch and th are each one sound, even though each is spelled with two letters."], "ref": "Lecture 17 · p6 · Lecture 18 · p6 · Lecture 19 · p6", "media": {"image": "assets/slides/lecture17/006.webp", "caption": "Lecture 17 · p6"}}, {"main": "**Consonants can also form clusters (groups of consonants in a row) before or after the vowel.** A cluster before the vowel is an **onset**, as in split, flat, black and glad. A cluster after the vowel is a **coda**, as in desk, help, milk and lamp.", "sub": ["The order of the consonants is a mirror image around the vowel. For example, l sits right next to the vowel in both flat and help. So flat is a word, and lfat is impossible.", "Each real word has an impossible version that puts the wrong consonant next to the vowel, such as help and hepl, or lamp and lapm.", "Sblit and desb are impossible too. That is why a product called desb would sound un-English."], "ref": "Lecture 17 · p6 · Lecture 18 · p6 · Lecture 19 · p6", "media": {"image": "assets/slides/lecture17/006.webp", "caption": "Lecture 17 · p6"}}, {"main": "**A pair of consonants can be fine across a syllable break but impossible at the start of a syllable.** Atlantic is a word because t and l are on opposite sides of a syllable break (At-lan-tic). Tlantic is impossible because tl cannot start an English syllable.", "sub": ["The sound ng can end a syllable, but it can never start one."], "ref": "Lecture 17 · p6 · Lecture 18 · p6 · Lecture 19 · p6", "media": {"image": "assets/slides/lecture17/006.webp", "caption": "Lecture 17 · p6"}}, {"main": "**Each language has its own phonotactics.** Mandarin allows only nasal sounds (sounds made with air going out through the nose, like n and ng) at the end of a syllable. Russian and Polish allow clusters like zb or dl at the start of a word.", "sub": ["Spanish speakers add an e before st at the start of a word, as in estadio."], "ref": "Lecture 17 · p6 · Lecture 18 · p6 · Lecture 19 · p6", "media": {"image": "assets/slides/lecture17/006.webp", "caption": "Lecture 17 · p6"}}, {"main": "**Guessing the next letter of a word depends on phonotactics, and each guess is a probability distribution.** After a vowel, almost any letter can come next, so the distribution is **flat** (the probability is spread out over many letters). At the start of a word, the choices narrow down to what an English onset allows.", "sub": ["After ra, almost any letter can come next, such as t, n, r or l, so the distribution is flat.", "After skr, the distribution is **sharply peaked** (most of the probability goes to a few vowels)."], "end": "So a GPT trained only on this guessing game learns English syllable structure. This is because guessing the next letter is the same task as an LLM predicting the sixteenth item from the first fifteen.", "ref": "Lecture 17 · p7 · Lecture 18 · p7 · Lecture 19 · p7", "media": {"image": "assets/slides/lecture17/007.webp", "caption": "Lecture 17 · p7"}}, {"main": "**At the start of a word, each first letter or cluster allows only a few next letters.** After sp, only l, r or a vowel can come next, never n. After k, a vowel or n can come next, as in knee, but never t.", "sub": ["After b or f, only r, l or a vowel can come next, never n.", "After sh, only a vowel or r can come next, as in shrimp.", "After skr, or after m at the start of a word, only a vowel can come next."], "ref": "Lecture 17 · p7 · Lecture 18 · p7 · Lecture 19 · p7", "media": {"image": "assets/slides/lecture17/007.webp", "caption": "Lecture 17 · p7"}}, {"main": "**Inside a word, the letters so far can make one next letter almost certain.** After bram, the next letter is almost certainly b, as in bramble.", "sub": ["A new syllable could also start there, so b is not the only possible next letter."], "ref": "Lecture 17 · p7 · Lecture 18 · p7 · Lecture 19 · p7", "media": {"image": "assets/slides/lecture17/007.webp", "caption": "Lecture 17 · p7"}}, {"main": "**After pl, st and th at the start of a word, the next letter is limited too.** After pl, only a vowel can come next, as in play. After st, a vowel or r can come next, as in star and street, but not l or k.", "sub": ["After th, r, w or a vowel can come next, as in three, thwart and thin, but not l or n."], "ref": "Lecture 17 · p7 · Lecture 18 · p7 · Lecture 19 · p7", "media": {"image": "assets/slides/lecture17/007.webp", "caption": "Lecture 17 · p7"}}], "questions": [{"source": "His question 3", "q": "Which could be English words: blick, bnick, sblat, splat, dlag, lisk, lisb, lapm, lamp? For each one that could not, name the problem.", "a": "Blick, splat, lisk and lamp could be English words.\n\nBnick, sblat and dlag could not be English words. This is because bn, sb and dl cannot start a syllable in English.\n\nLisb and lapm could not be English words. This is because sb and pm cannot end a syllable in English."}, {"source": "His question 4", "q": "Each of these starts an English word: pl_, st_ and th_. What could come next, and what could not?", "a": "After pl, only a vowel can come next, as in play. So a consonant such as n cannot come next.\n\nAfter st, a vowel or r can come next, as in star and street. But l and k cannot come next.\n\nAfter th, r, w or a vowel can come next, as in three, thwart and thin. But l and n cannot come next."}, {"source": "Predicted (Lectures 17–18) 22", "q": "After which start is the next-letter distribution flatter, ra_ or skr_? Why?", "a": "The next-letter distribution is flatter after ra than after skr. This is because ra ends in a vowel, and after a vowel almost any letter can come next. So the probability is spread out over many letters. After skr, only a vowel can come next. So most of the probability goes to a few vowels, and the distribution is sharply peaked."}, {"source": "Predicted (Lectures 17–18) 23", "q": "Why is Atlantic an English word but tlantic impossible?", "a": "Atlantic is an English word, but tlantic is impossible. This is because in Atlantic, the t and l are on opposite sides of a syllable break (At-lan-tic), so each syllable follows the rules. In tlantic, tl would have to start a syllable. English does not allow tl at the start of a syllable, so tlantic is impossible."}, {"source": "Predicted (Lectures 17–18) 24", "q": "Could ngop be an English word? Could flim?", "a": "Ngop could not be an English word. This is because the sound ng can end a syllable, as in ring, but it can never start one.\n\nFlim could be an English word. This is because fl is an allowed onset (the consonants before the vowel), as in flat, and im is an allowed ending."}, {"source": "Predicted (Lectures 17–18) 25", "q": "Why does a GPT trained only to guess the next letter end up knowing English syllable structure?", "a": "A GPT trained only to guess the next letter ends up knowing English syllable structure because the patterns of English syllables determine which letters can come next. This is because its guesses can only get better by matching those patterns. So as it learns, its probability distributions take on the shape of those patterns. They are flat after a vowel and sharply peaked after a start such as skr."}, {"source": "Predicted (Lectures 17–18) 26", "q": "Which letter cannot come next after sp_ at the start of a word: l, r, n or a?", "a": "N cannot come next after sp at the start of a word. This is because spn is not an allowed English onset (the consonants before the vowel). After sp, only l, r or a vowel can come next, as in split, spring and spa."}, {"source": "Predicted (Lectures 17–18) 27", "q": "Which letter cannot come next after k_ at the start of a word: a, n or t?", "a": "T cannot come next after k at the start of a word. This is because kt cannot start an English syllable. After k, a vowel or n can come next, as in knee."}, {"source": "Predicted (Lectures 17–18) 28", "q": "What can come next after b_ or f_ at the start of a word, and what cannot?", "a": "After b or f at the start of a word, only r, l or a vowel can come next, as in bring, black, frog and flat. N cannot come next. This is because bn and fn cannot start an English syllable."}, {"source": "Predicted (Lectures 17–18) 29", "q": "What can come next after sh_ at the start of a word?", "a": "After sh at the start of a word, only a vowel or r can come next, as in ship and shrimp. This is because shr is the only consonant cluster that English allows starting with sh."}, {"source": "Predicted (Lectures 17–18) 30", "q": "What can come next after skr_?", "a": "After skr, only a vowel can come next, as in scream and scrap (where the skr sound is spelled scr). This is because skr already fills the whole onset (the consonants before the vowel). So no other consonant can be added before the vowel."}, {"source": "Predicted (Lectures 17–18) 31", "q": "Why are lfat, hepl and lapm impossible when flat, help and lamp are words?", "a": "Lfat, hepl and lapm are impossible because the order of a cluster is a mirror image around the vowel. In flat and help, the l sits right next to the vowel. In lamp, the m sits right next to the vowel. Each impossible version puts the wrong consonant next to the vowel. So it breaks the mirror order, and it cannot be an English word."}, {"source": "Predicted (Lectures 17–18) 32", "q": "Is ship a consonant, vowel, consonant word even though it has four letters?", "a": "Yes, ship is a consonant, vowel, consonant word even though it has four letters. This is because the pattern is about sounds, not letters, and sh is one sound. So ship is the consonant sh, the vowel i and the consonant p."}]}, {"id": "m3-agentic", "title": "Agentic systems and Software 3.0", "lectures": "Lectures 17 and 18 · repeated in Lecture 19", "blocks": [{"main": "**An agentic system is a group of LLMs (large language models) connected so that one LLM's output becomes the next LLM's input.** In AI today, an **agent** is just an LLM. In one example, an outline LLM plans the answer, and a writing LLM writes it.", "sub": ["A critic LLM checks the draft, and a revision LLM works back and forth with the critic.", "A final LLM produces the answer that the user sees."], "ref": "Lecture 17 · p4 · Lecture 18 · p2 · Lecture 19 · p2", "media": {"image": "assets/slides/lecture17/004.webp", "caption": "Lecture 17 · p4"}}, {"main": "**The critic loop sends the draft back and forth between the critic and the reviser.** The loop continues until the critic is satisfied or a limit is reached. This loop greatly reduced **hallucination** (when an LLM makes up false statements).", "sub": ["Once each LLM is trained, its weights usually do not change.", "The agents share a common memory, where they write and read information."], "ref": "Lecture 17 · p4 · Lecture 18 · p2 · Lecture 19 · p2", "media": {"image": "assets/slides/lecture17/004.webp", "caption": "Lecture 17 · p4"}}, {"main": "**Software 1.0, 2.0 and 3.0 are three ways to build a program.** **Software 1.0** is writing a program in a programming language such as Python. **Software 2.0** is training a neural network on input and output data, so the program is the network's weights.", "sub": ["**Software 3.0** is having an agentic system build and run the program from instructions written in plain English.", "Building a program this way is called **vibe coding**."], "ref": "Lecture 18 · p8 · Lecture 19 · p8", "media": {"image": "assets/slides/lecture18/008.webp", "caption": "Lecture 18 · p8"}}], "questions": [{"source": "His question 5", "q": "What is an agentic system, in terms of LLMs? Describe the example system.", "a": "An agentic system is a graph (a set of connected parts) of LLMs (large language models), each with its own job. The LLMs are connected so that one LLM's output becomes the next LLM's input.\n\nIn the example system, one LLM outlines, one writes, one critiques, one revises and one produces the final version. The critic and the reviser form a loop. So the draft keeps going back until the critic is satisfied or the limit is reached."}, {"source": "His question 6", "q": "What does the critic loop do, and what does it prevent that was common in earlier LLMs?", "a": "The critic loop sends the draft back and forth between the critic and the reviser until the critic is satisfied. The critic checks each draft, and the reviser fixes the errors the critic finds. So errors are caught and fixed before the answer is shown to the user.\n\nThe critic loop prevents hallucination (when an LLM makes up false statements), which was a common problem in earlier LLMs."}, {"source": "Predicted (Lectures 17–18) 33", "q": "What would happen if the critic LLM were removed?", "a": "If the critic LLM were removed, the draft would go straight from writing to the final answer without being checked. This is because the critic is the LLM that checks the draft. So more made-up statements would reach the user. The critic loop is what greatly reduced hallucination, so without it that reduction would be lost."}, {"source": "Predicted (Lectures 17–18) 34", "q": "What is the difference between Software 2.0 and Software 3.0?", "a": "The difference between Software 2.0 and Software 3.0 is how the program gets built.\n\nIn Software 2.0, a neural network is trained on input and output data, so the program is the network's weights.\n\nIn Software 3.0, an agentic system builds and runs the program from plain English instructions. Building a program this way is called vibe coding."}]}, {"id": "m3-hidden-word", "title": "What an LLM learns: guessing a hidden word", "lectures": "Lecture 19", "blocks": [{"ref": "Lecture 19 · p9", "main": "**An LLM (large language model) learns by guessing a hidden word and then changing its weights a little.** In the sentence \"The chef cracks the,\" the last word is hidden. The model reads the four words before the gap. Then it has to predict the word that fills the gap.", "sub": ["Each word before the gap gives a clue about the hidden word. These clue relationships are called **interdependencies** (one part of a sequence helps predict another part).", "The model does not know the answer, so it spreads its bets. A bet is the probability the model gives to one word. It bets the most on \"egg,\" less on \"nut\" and the least on \"code.\"", "**Learning means nudging the weights (changing each weight a little) so that these guesses get better.** After the true word is revealed, the weights change a little. Because of that change, the right word gets a bigger bet next time."], "end": "The same idea holds when the signal (the sequence the model reads) contains words, sounds and images. The model still guesses a hidden piece and nudges its weights, so the way it learns stays the same.", "media": {"image": "assets/slides/lecture19/009.webp", "caption": "Lecture 19 · p9"}}], "questions": [{"source": "Predicted (Lecture 19) 1", "q": "How does an LLM learn from the sentence \"The chef cracks the ?\"", "a": "An LLM learns from this sentence by guessing the hidden last word and then changing its weights a little.\n\nThis is because each word before the gap gives a clue about the hidden word. So the model bets the most on \"egg,\" less on \"nut\" and the least on \"code.\" When the true word is revealed, the weights are nudged. So the right word gets a bigger bet next time."}, {"source": "Predicted (Lecture 19) 2", "q": "Why does the model give \"egg,\" \"nut\" and \"code\" different bets instead of one answer?", "a": "The model gives three different bets because it does not know the hidden word. All three words could follow \"The chef cracks the.\" The words before the gap make \"egg\" the most likely. So \"egg\" gets the largest bet, \"nut\" gets a smaller bet and \"code\" gets the smallest bet."}, {"source": "Predicted (Lecture 19) 3", "q": "What does learning change in an LLM, and in which direction?", "a": "Learning changes the weights. Each weight is nudged, which means it changes a little. The weights change in the direction that gives the right word a bigger bet the next time."}]}, {"id": "m3-conversion", "title": "Turning speech and images into rows of vectors", "lectures": "Lecture 19", "blocks": [{"ref": "Lecture 19 · p10", "main": "**An LLM can only read a row of vectors (lists of numbers), so speech and images have to be converted first.** Text, speech and images arrive in three different forms.", "sub": ["**Text** is already a row of pieces, such as \"Now,\" \"crack,\" \"the\" and \"egg,\" and each piece can become one vector.", "**Speech** is air pressure changing in time, and there are no words in the sound itself.", "An **image** is a grid of light, and it contains no words either."], "end": "So the first job is a conversion. Speech and images both have to become rows of vectors, because that is all the LLM can read.", "media": {"image": "assets/slides/lecture19/010.webp", "caption": "Lecture 19 · p10"}}, {"ref": "Lecture 19 · p11", "main": "**Speech is turned into a row of vectors by slicing it in time.** The sound is cut into short slices, and each slice is called a **frame**. Each slice is about 20 milliseconds long.", "sub": ["The slices go through a **speech encoder** (a neural network that was trained on a large amount of audio). One vector comes out for each slice.", "**One second of speech becomes 50 vectors.** This is because each slice is about 20 milliseconds long, and 50 slices of that length fill one second. Each slice gives one vector.", "The vectors stay in time order. The first slice gives the first vector, and the last slice gives the last vector."], "end": "So speech is now a row, just like a sentence, and the LLM can read it one vector after another.", "media": {"image": "assets/slides/lecture19/011.webp", "caption": "Lecture 19 · p11"}}, {"ref": "Lecture 19 · p12", "main": "**An image is turned into a row of vectors by cutting it into patches.** A **patch** is one small square of the image. A grid cuts the image of an egg in a pan into 16 patches.", "sub": ["The patches are laid out in a row in **reading order** (left to right along the top, then left to right along the next line down). This turns the image into a sequence, like a sentence.", "The patches go through a **vision encoder**. One vector comes out for each patch, so 16 patches give 16 vectors.", "Real systems use much smaller patches of 14 to 16 pixels. Smaller patches mean more patches for the same image, so one image gives hundreds of vectors."], "end": "So both conversions follow the same steps. The signal is cut into small pieces, the pieces are kept in order, and an encoder gives one vector for each piece.", "media": {"image": "assets/slides/lecture19/012.webp", "caption": "Lecture 19 · p12"}}], "questions": [{"source": "Predicted (Lecture 19) 4", "q": "Why is text easier for an LLM to read than speech or an image?", "a": "Text is easier because it is already a row of pieces. Each piece, such as \"Now,\" \"crack,\" \"the\" or \"egg,\" can become one vector.\n\nSpeech is air pressure changing in time, and an image is a grid of light. Neither one contains words or separate pieces. So both have to be converted into rows of vectors first."}, {"source": "Predicted (Lecture 19) 5", "q": "How is speech turned into a row of vectors?", "a": "Speech is turned into a row of vectors by slicing it in time. First, the sound is cut into short slices called frames, each about 20 milliseconds long. Then the slices go through a speech encoder, which is a neural network trained on a large amount of audio. One vector comes out for each slice, and the vectors stay in time order."}, {"source": "Predicted (Lecture 19) 6", "q": "Why does one second of speech become 50 vectors?", "a": "One second of speech becomes 50 vectors because each slice gives one vector. Each slice is about 20 milliseconds long, and 50 slices of that length fill one second. So one second gives 50 vectors."}, {"source": "Predicted (Lecture 19) 7", "q": "How is an image turned into a row of vectors?", "a": "An image is turned into a row of vectors by cutting it into patches. First, a grid cuts the image into small squares called patches. Then the patches are laid out in a row in reading order, so the image becomes a sequence. Last, a vision encoder gives one vector for each patch."}, {"source": "Predicted (Lecture 19) 8", "q": "The egg example gives 16 vectors. Why does one image give hundreds of vectors in real systems?", "a": "One image gives hundreds of vectors in real systems because real systems use much smaller patches. Their patches are only 14 to 16 pixels. Smaller patches mean more patches for the same image. Each patch gives one vector, so there are hundreds of vectors."}, {"source": "Predicted (Lecture 19) 9", "q": "What is the similarity between converting speech and converting an image, and what is the difference?", "a": "The similarity is that both are cut into small pieces, the pieces are kept in order, and an encoder gives one vector for each piece.\n\nThe difference is what is cut. Speech is cut in time into frames of about 20 milliseconds. An image is cut in space into square patches, which are then placed in reading order."}]}, {"id": "m3-one-row", "title": "One row, three senses: cross-modal dependencies", "lectures": "Lecture 19", "blocks": [{"ref": "Lecture 19 · p13", "main": "**Image patches, speech frames and words can all be placed in one row, and the model guesses the hidden piece.** The image patches come first, the speech frames come next, and the words come last. The words are \"Now,\" \"crack\" and \"the,\" and the word after them is hidden.", "sub": ["The words before the gap still give clues, the same as in a row that holds only text.", "Clues now also come from the other senses. A patch that contains an egg helps the model guess the hidden word. The sound of cracking helps too.", "A link between two different kinds of signal is called a **cross-modal dependency**."], "end": "So the game is exactly the same as before. The only new thing is that some of the clues come from other senses.", "media": {"image": "assets/slides/lecture19/013.webp", "caption": "Lecture 19 · p13"}}, {"ref": "Lecture 19 · p14", "main": "**\"Three cute puppies\" is one event given in three forms, and training puts all three in one row.** The first form is an image of three puppies, cut into 18 patches. The second form is the phrase spoken aloud. The third form is the three written words.", "sub": ["The spoken phrase is shown as a **spectrogram** (a display of a sound laid out in time). Time runs from left to right. Higher up means a higher frequency. A darker area means more energy.", "Each thin column of the spectrogram is one frame. Each word has its own stretch of time, with \"three\" first and \"puppies\" last.", "The voice is a speech synthesizer (an MBROLA diphone voice). It is not a recording of a person."], "end": "So the image, the sound and the words are three views of one event. In training, one piece of the row is hidden, and the model has to guess it.", "media": {"image": "assets/slides/lecture19/014.webp", "caption": "Lecture 19 · p14"}}], "questions": [{"source": "Predicted (Lecture 19) 10", "q": "What is a cross-modal dependency? Give an example.", "a": "A cross-modal dependency is a link between two different kinds of signal, in which a piece from one sense helps predict a piece from another sense.\n\nFor example, in \"Now crack the ?\", an image patch that contains an egg helps the model guess the hidden word. The sound of cracking helps too."}, {"source": "Predicted (Lecture 19) 11", "q": "When image patches and speech frames are added to the row, what stays the same and what changes?", "a": "The game stays the same. The model still guesses the hidden piece from the pieces it can read, and the words before the gap still give clues.\n\nWhat changes is where some of the clues come from. Some clues now come from image patches and speech frames."}, {"source": "Predicted (Lecture 19) 12", "q": "In the spectrogram of \"three cute puppies,\" what do left to right, height and darkness mean?", "a": "Left to right is time, so \"three\" comes first and \"puppies\" comes last. Height is frequency, so higher up means a higher frequency. Darkness is energy, so a darker area means more energy. Each thin column is one frame."}, {"source": "Predicted (Lecture 19) 13", "q": "Why are the image, the spectrogram and the words called three views of one event?", "a": "They are called three views of one event because all three describe the same thing, which is three cute puppies. The image gives it as patches, the speech gives it as frames, and the text gives it as words. In training, all three go into one row."}]}, {"id": "m3-training", "title": "The three training examples: hidden word, hidden sound frame, hidden image patch", "lectures": "Lecture 19", "blocks": [{"ref": "Lecture 19 · p15", "main": "**In training example 1, the hidden piece is a word, and the image and the sound settle the guess.** The row holds the image, then the sound, then the words \"three\" and \"cute.\" The word after \"cute\" is hidden.", "sub": ["With the words alone, the bets are spread out. This is because many endings fit after \"three cute,\" such as \"kittens,\" \"puppies\" and \"babies.\"", "With the image and the sound, the bet piles up on \"puppies.\" This is because the image contains puppies, and the sound contains the spoken word \"puppies.\"", "The true word is then revealed, and the model is graded on how much it bet on that word. The model bet 0.85 on \"puppies.\""], "end": "So the nudge to the weights is small. This is because the model bet a lot on the true word, so the error is small, and a small error moves the weights only a little.", "media": {"image": "assets/slides/lecture19/015.webp", "caption": "Lecture 19 · p15"}}, {"ref": "Lecture 19 · p16", "main": "**In training example 2, the hidden piece is a frame of sound, and three clues help the model guess it.** The row is put in a new order, with the image first, then the words, then the sound. This is like teaching the model to speak a sentence it was given. The sound is predicted frame by frame, from left to right.", "sub": ["The frames already heard are the first clue. The voice and the **formants** (frequency regions with strong energy) change smoothly, so the last few frames say a lot about the next one.", "The words are the second clue. They say which sound should come next, and here it is the vowel in \"pup.\"", "The image is the third clue. It contains puppies, so it backs up the words. It is a weaker clue here.", "A frame is a column of numbers. Each number is how much energy there is in one frequency band. The guess is close to the true frame, but it is not exact."], "end": "So the error is how far each guessed number is from the true number, and that error nudges the weights.", "media": {"image": "assets/slides/lecture19/016.webp", "caption": "Lecture 19 · p16"}}, {"ref": "Lecture 19 · p17", "main": "**In training example 3, the hidden piece is a patch of the image, and the biggest error is the colour.** The row is put in a new order again, with the words first, then the sound, then the image. This is like teaching the model to draw what it was told. The patches are predicted in reading order.", "sub": ["The patches already drawn are the first clue. Above the hidden patch is background. To its left are two puppies, so the model has seen what a puppy in this image looks like.", "The words are the second clue. \"Three\" says a third puppy must appear, because only two are drawn. \"Puppies\" says to expect dog ears.", "The sound is the third clue. It carries the same words, so it backs up the text.", "The model guesses a blurry puppy ear in the average colour of the first two puppies. The true puppy is dark."], "end": "So the biggest error is the colour. This is because no clue in the words, the sound or the patches already drawn said the third puppy would be dark. Only systems that also produce images are trained this way.", "media": {"image": "assets/slides/lecture19/017.webp", "caption": "Lecture 19 · p17"}}], "questions": [{"source": "Predicted (Lecture 19) 14", "q": "How do the model's bets on the next word change when the image and the sound are added to \"three cute\"?", "a": "With the words alone, the bets are spread out over \"kittens,\" \"puppies\" and \"babies.\" This is because many endings fit after \"three cute.\"\n\nWith the image and the sound, the bet piles up on \"puppies.\" This is because the image contains puppies, and the sound contains the spoken word \"puppies.\""}, {"source": "Predicted (Lecture 19) 15", "q": "The model bet 0.85 on \"puppies,\" and the true word is \"puppies.\" Is the nudge to the weights large or small? Why?", "a": "The nudge to the weights is small. This is because the model is graded on how much it bet on the true word. It bet 0.85, which is a lot, so the error is small. A small error moves the weights only a little."}, {"source": "Predicted (Lecture 19) 16", "q": "What would happen to the nudge if the model had bet only a little on \"puppies\"?", "a": "The nudge would be larger. This is because a small bet on the true word is a large error. A larger error moves the weights more, so that the true word gets a bigger bet next time."}, {"source": "Predicted (Lecture 19) 17", "q": "Name the three clues that help the model predict a hidden sound frame, and say what each one gives.", "a": "The first clue is the frames already heard. The voice and the formants change smoothly, so the last few frames say a lot about the next one.\n\nThe second clue is the words. They say which sound should come next, which here is the vowel in \"pup.\"\n\nThe third clue is the image. It contains puppies, so it backs up the words, but it is a weaker clue here."}, {"source": "Predicted (Lecture 19) 18", "q": "What is the error when the model guesses a sound frame?", "a": "The error is how far the guess is from the true frame. A frame is a column of numbers, and each number is how much energy there is in one frequency band. The error is how far apart each guessed number is from the matching true number. That error nudges the weights."}, {"source": "Predicted (Lecture 19) 19", "q": "In training example 3, why is the colour the biggest error?", "a": "The colour is the biggest error because no clue gave the colour of the third puppy. The model guessed a puppy ear in the average colour of the first two puppies. The true puppy is dark. Nothing in the words, the sound or the patches already drawn said the third puppy would be dark."}, {"source": "Predicted (Lecture 19) 20", "q": "What do the words \"three\" and \"puppies\" tell the model about the hidden image patch?", "a": "\"Three\" tells the model that a third puppy must appear, because only two puppies have been drawn so far. \"Puppies\" tells the model to expect dog ears. So the model guesses a puppy ear for the hidden patch."}, {"source": "Predicted (Lecture 19) 21", "q": "Are all systems trained to predict image patches?", "a": "No. Only systems that also produce images are trained to predict image patches. Systems that only read images usually skip this step. This is because predicting a patch is like teaching the model to draw what it was told."}]}, {"id": "m3-clues", "title": "Every piece can be the hidden one: two kinds of clue", "lectures": "Lecture 19", "blocks": [{"ref": "Lecture 19 · p18", "main": "**Any piece of the row can be the hidden one, and each sense gives a clue for it.** The hidden piece can be a word, a sound frame or an image patch.", "sub": ["For a **hidden word**, the words \"three cute\" call for a plural noun, the sound has just spoken the word, and the image contains puppies.", "For a **hidden frame**, the words say which sound comes next, the voice and the formants carry on, and the image backs up which word is being said.", "For a **hidden patch**, the word \"three\" says one more puppy is coming, the sound gives the same words in heard form, and the fur and the background carry on."], "end": "So a clue from the same sense says how the signal continues, and clues from the other senses say what the thing is. Training on all three senses together helps, because each sense fills gaps that the others leave.", "media": {"image": "assets/slides/lecture19/018.webp", "caption": "Lecture 19 · p18"}}], "questions": [{"source": "Predicted (Lecture 19) 22", "q": "What is the difference between a clue from the same sense as the hidden piece and a clue from another sense?", "a": "A clue from the same sense mostly says how the signal continues. Grammar does this for a hidden word, smooth formants do it for a hidden frame, and fur and background do it for a hidden patch.\n\nClues from the other senses mostly say what the thing is. Here they say puppies, three of them."}, {"source": "Predicted (Lecture 19) 23", "q": "For a hidden sound frame, which clue comes from the same sense, and what does it tell the model?", "a": "The clue from the same sense is that the voice and the formants carry on from the frames already heard. It tells the model how the sound continues. The words and the image are the other senses, and they say which word is being said."}, {"source": "Predicted (Lecture 19) 24", "q": "Why does training on words, sound and images together help?", "a": "Training on all three senses together helps because each sense fills gaps that the others leave. A clue from the same sense says how the signal continues. Clues from the other senses say what the thing is. So with all three senses, the model has both kinds of clue for every hidden piece."}]}, {"id": "m3-talking-back", "title": "Talking back, what is new and what stays the same", "lectures": "Lecture 19", "blocks": [{"ref": "Lecture 19 · p19", "main": "**The model speaks by predicting codes for sound, and a decoder turns the codes back into sound.** First, sound is compressed into discrete codes (separate numbered units), such as 417, 82 and 903. Each code works like a new word added to the vocabulary.", "sub": ["The model predicts the next code exactly as it predicts the next word. So speaking is the same guessing game again.", "A **decoder** then turns the row of predicted codes back into a sound wave that can be heard."], "end": "So the model gives the codes, and the decoder gives the sound.", "media": {"image": "assets/slides/lecture19/019.webp", "caption": "Lecture 19 · p19"}}, {"ref": "Lecture 19 · p19", "main": "**Three things are new when a model is trained on words, sounds and images, and one thing stays the same.** The first new thing is a **shared currency**, in which everything becomes vectors in one row. The second is **data where the senses appear together**. The third is **a schedule that protects what was already learned**.", "sub": ["What stays the same is the learning rule, which is to find the dependencies in the signal."], "end": "So the model still guesses a hidden piece and nudges its weights. The signal has only become wider, because it now holds words, sounds and images.", "media": {"image": "assets/slides/lecture19/019.webp", "caption": "Lecture 19 · p19"}}], "questions": [{"source": "Predicted (Lecture 19) 25", "q": "How does the model talk back?", "a": "The model talks back by predicting codes for sound. First, sound is compressed into discrete codes, and each code works like a new word in the vocabulary. Then the model predicts the next code exactly as it predicts the next word. Last, a decoder turns the codes back into a sound wave."}, {"source": "Predicted (Lecture 19) 26", "q": "What three things are new when an LLM is trained on words, sounds and images?", "a": "The first new thing is a shared currency, in which everything becomes vectors in one row. The second is data where the senses appear together. The third is a schedule that protects what was already learned."}, {"source": "Predicted (Lecture 19) 27", "q": "What stays the same when the signal holds words, sounds and images?", "a": "The learning rule stays the same. The model still finds the dependencies in the signal by guessing a hidden piece and nudging its weights. The signal has only become wider."}]}]}, "review": {"title": "Final exam review guide · Module III", "lead": "Every question on Lectures 17 to 19 with its answer, written in plain steps, the answer first and then the reason.", "note": "No review sheet for the final has been handed out yet. The questions on the new Lecture 19 slides are predictions written from the slides. The questions on Lectures 17 and 18 are the ones from the Module II study page, including his Lab 9 questions.", "sets": [{"id": "his", "title": "Lectures 17 and 18 · 6 of his questions", "about": "His Lab 9 questions and the heads question he said is on the exam. On November 10 he said the LLM part is kept for the final.", "prefix": "His question", "items": [{"number": 1, "question": "What is the difference between the input and output of the vowel network and those of an LLM?", "answer": "The difference is that the vowel network takes in one vector and decides among five categories, while an LLM takes in many vectors and decides among a whole vocabulary.\n\nThe vowel network's input is one vector, F1 and F2. Its output decides among five categories.\n\nAn LLM's input is many vectors in sequence, such as the words so far. Its output decides among a whole vocabulary for the next item.", "source": "His question 1"}, {"number": 2, "question": "What are heads, and how do they relate to layers?", "answer": "A head is one expert, which is a set of weights that gives its own opinion on how to improve the vectors. Heads sit side by side inside each layer. The layer combines all of its heads' opinions into improved vectors. The layers come one after another from the input to the output. So each layer uses its heads to improve the vectors again.", "source": "His question 2"}, {"number": 3, "question": "Which could be English words: blick, bnick, sblat, splat, dlag, lisk, lisb, lapm, lamp? For each one that could not, name the problem.", "answer": "Blick, splat, lisk and lamp could be English words.\n\nBnick, sblat and dlag could not be English words. This is because bn, sb and dl cannot start a syllable in English.\n\nLisb and lapm could not be English words. This is because sb and pm cannot end a syllable in English.", "source": "His question 3"}, {"number": 4, "question": "Each of these starts an English word: pl_, st_ and th_. What could come next, and what could not?", "answer": "After pl, only a vowel can come next, as in play. So a consonant such as n cannot come next.\n\nAfter st, a vowel or r can come next, as in star and street. But l and k cannot come next.\n\nAfter th, r, w or a vowel can come next, as in three, thwart and thin. But l and n cannot come next.", "source": "His question 4"}, {"number": 5, "question": "What is an agentic system, in terms of LLMs? Describe the example system.", "answer": "An agentic system is a graph (a set of connected parts) of LLMs (large language models), each with its own job. The LLMs are connected so that one LLM's output becomes the next LLM's input.\n\nIn the example system, one LLM outlines, one writes, one critiques, one revises and one produces the final version. The critic and the reviser form a loop. So the draft keeps going back until the critic is satisfied or the limit is reached.", "source": "His question 5"}, {"number": 6, "question": "What does the critic loop do, and what does it prevent that was common in earlier LLMs?", "answer": "The critic loop sends the draft back and forth between the critic and the reviser until the critic is satisfied. The critic checks each draft, and the reviser fixes the errors the critic finds. So errors are caught and fixed before the answer is shown to the user.\n\nThe critic loop prevents hallucination (when an LLM makes up false statements), which was a common problem in earlier LLMs.", "source": "His question 6"}]}, {"id": "kept", "title": "Lectures 17 and 18 · 34 predicted questions", "about": "Predicted questions from the Module II study page for Lectures 17 and 18.", "prefix": "Predicted (Lectures 17–18)", "items": [{"number": 1, "question": "How does the all-or-none behavior of neurons connect to the sigmoid?", "answer": "The all-or-none behavior of neurons is the same idea as the sigmoid. This is because a real neuron is either firing or not firing. The sigmoid turns an inner product into a number near 0 (off) or near 1 (on), with a steep change in between. So an artificial neuron that uses the sigmoid behaves the same way as a real neuron.", "source": "Predicted (Lectures 17–18) 1"}, {"number": 2, "question": "What do parallel and distributed mean in Parallel Distributed Processing?", "answer": "Parallel means that many neurons calculate their activations at the same time.\n\nDistributed means that the information from the inputs is spread across all the neurons. So the information is not stored in one place.", "source": "Predicted (Lectures 17–18) 2"}, {"number": 3, "question": "What does a single neuron take in and give back? What about a neural network?", "answer": "A single neuron takes in a vector and gives back one number. That number is the inner product, which is each input multiplied by its weight, with the results added together.\n\nA neural network takes in one vector and gives back a vector of decisions. This is because a neural network repeats the inner product layer after layer. So the network ends with several outputs instead of just one number.", "source": "Predicted (Lectures 17–18) 3"}, {"number": 4, "question": "Why can't the vowel network model a sentence or speech over time?", "answer": "The vowel network cannot model a sentence or speech over time because it takes one static vector and makes one decision. That vector is F1 and F2 (the first two formants) from one moment. But speech changes all the time, and a sentence is many words, one after another. So modeling speech needs a network that works through a sequence.", "source": "Predicted (Lectures 17–18) 4"}, {"number": 5, "question": "What makes Jordan's network recurrent, and why did he build it?", "answer": "Jordan's network is recurrent because it sends its own output back into part of its input. It copies the output into the state units. So what it produced at one moment helps predict the next moment.\n\nJordan built it because speech production changes over time. Features such as nasality and lip rounding switch on and off at different moments. So he needed a network that could follow these changes step by step.", "source": "Predicted (Lectures 17–18) 5"}, {"number": 6, "question": "How is a recurrent network different from an nn.Sequential network?", "answer": "A recurrent network is different from an nn.Sequential network because it loops its output back into its input. A Sequential network passes the input through the layers once, from the input to the output, and makes one decision. A recurrent network sends its output back in as part of its next input. So a recurrent network works through a sequence step by step.", "source": "Predicted (Lectures 17–18) 6"}, {"number": 7, "question": "How does GPT use the same idea as Jordan's network?", "answer": "GPT uses the same idea as Jordan's network because it also feeds its own output back into its input. It predicts the next word and adds that word to the prompt. Then it predicts again, using the longer prompt. So GPT produces text one word at a time.", "source": "Predicted (Lectures 17–18) 7"}, {"number": 8, "question": "An LLM is given 15 vectors and predicts the sixteenth. Name three things the vectors can stand for.", "answer": "Three things the vectors can stand for are the words of a sentence, the frames of a spectrogram and the patches of an image. They can also stand for the amino acids of a protein. The same kind of prediction works for all of them. This is because the LLM only works with lists of numbers, whatever those numbers stand for.", "source": "Predicted (Lectures 17–18) 8"}, {"number": 9, "question": "What does the sixteenth vector look like, and does it add up to anything?", "answer": "The sixteenth vector is a probability distribution over what could come next, and its numbers add up to one.\n\nThe sixteenth vector has one number for each possible next item, such as each English word. Each number is how likely that item is to come next.\n\nIt adds up to one because it is a probability distribution. The probabilities of all the possible next items always add up to one.", "source": "Predicted (Lectures 17–18) 9"}, {"number": 10, "question": "Why is the next word barks and not bark in \"the dog that my parents, who I love very much, ... \"?", "answer": "The next word is barks and not bark because barks goes with the singular word dog. This is true no matter how many words come in between. It holds even when the plural word parents comes in between. To predict barks, an LLM has to use a word far back in the sequence. It learns to do this from data, by computing inner products layer after layer.", "source": "Predicted (Lectures 17–18) 10"}, {"number": 11, "question": "Why can an LLM hallucinate?", "answer": "An LLM can hallucinate because it predicts from past data. When it meets something its data does not cover, its prediction can turn into a guess. So it can make things up, and this is called hallucination.", "source": "Predicted (Lectures 17–18) 11"}, {"number": 12, "question": "Describe the Gestalt principle of closure, and how an LLM uses it to learn.", "answer": "The Gestalt principle of closure is completing a familiar pattern that is not quite finished. For example, people see a triangle where none is drawn, and they see a broken circle as a whole circle.\n\nAn LLM (large language model) uses closure to learn by doing the same kind of completion. It predicts the missing next piece of a sequence again and again. When its prediction is wrong, it corrects its weights. So it learns by completing sequences over and over.", "source": "Predicted (Lectures 17–18) 12"}, {"number": 13, "question": "What is a cloze test, and why is an LLM's training like one?", "answer": "A cloze test is a test where words are removed from a text and people fill them in. So it tests knowledge by asking someone to complete a sequence.\n\nAn LLM's training is like a cloze test because the LLM (large language model) is trained by filling in the next word over and over. So for an LLM, knowing something means being able to complete the sequence.", "source": "Predicted (Lectures 17–18) 13"}, {"number": 14, "question": "Why do people see a triangle in the Gestalt figure?", "answer": "People see a triangle in the Gestalt figure because they complete the missing parts of a familiar pattern. No triangle is actually drawn, but people fill in what is missing. This completion is the Gestalt principle of closure.", "img": "assets/exam2/gen-kanizsa-triangle.svg", "alt": "Three black circles with wedges cut out, facing each other", "source": "Predicted (Lectures 17–18) 14"}, {"number": 15, "question": "In the classroom of experts, what are the classes and what are the students?", "answer": "In the classroom of experts, the classes are the layers and the students are the heads. This is because you visit the classes one after another, just as the layers come one after another. The students in each class each give a separate opinion at the same time, just as the heads in one layer work side by side. You combine those opinions before moving on to the next class. So each class is one layer, and each student in it is one head.", "source": "Predicted (Lectures 17–18) 15"}, {"number": 16, "question": "Which gives an LLM depth and which gives it width, heads or layers?", "answer": "Layers give an LLM depth, and heads give it width. This is because layers are rounds of improvement that come one after another, which adds depth. Heads work side by side inside the same layer, which adds width. So more layers means more rounds, and more heads means more experts in each round.", "source": "Predicted (Lectures 17–18) 16"}, {"number": 17, "question": "An LLM has 5 layers with 4 heads in each layer. How many heads does it have, and which of them work at the same time?", "answer": "The LLM has 20 heads, and the 4 heads inside the same layer work at the same time. This is because each of the 5 layers has 4 heads, and 5 times 4 is 20. The 4 heads inside one layer work side by side. The layers come one after another, so layer 2 works on the vectors that layer 1 improved. So heads in the same layer work at the same time, but heads in different layers do not.", "source": "Predicted (Lectures 17–18) 17"}, {"number": 18, "question": "The LLM predicts bark instead of barks after \"the dog that my parents ... \". Which weights change?", "answer": "When the LLM predicts bark instead of barks, the weights of every head in every layer change. This is because backpropagation calculates how much each weight contributed to the wrong prediction. Then each weight is adjusted a little in the direction that reduces the error. So the next prediction is closer to barks.", "source": "Predicted (Lectures 17–18) 18"}, {"number": 19, "question": "Where is the knowledge of an LLM stored?", "answer": "The knowledge of an LLM is stored in its weights. This is because each head is a set of weights, and those weights are what change when the model learns. So the knowledge is spread across all the heads in all the layers. The vowel network's knowledge is stored in its weights in the same way.", "source": "Predicted (Lectures 17–18) 19"}, {"number": 20, "question": "Why is an LLM called a dynamical system?", "answer": "An LLM is called a dynamical system because it works by giving a rule its own output again and again. A dynamical system is a rule that is repeatedly given its own output as input, starting from initial conditions (the starting numbers). In an LLM, the input vectors are the initial conditions. Each layer applies its weights to turn those vectors into better vectors, and the next layer takes those as its input. So the depth of the layers plays the role of time.", "source": "Predicted (Lectures 17–18) 20"}, {"number": 21, "question": "In the harmonic oscillator, which two numbers update, and in what order?", "answer": "In the harmonic oscillator, position x and velocity v update, and they take turns. First, the new x is calculated from the old v. Then, the new v is calculated from the new x. When these two steps are repeated over and over, x traces out a cosine shape.", "source": "Predicted (Lectures 17–18) 21"}, {"number": 22, "question": "After which start is the next-letter distribution flatter, ra_ or skr_? Why?", "answer": "The next-letter distribution is flatter after ra than after skr. This is because ra ends in a vowel, and after a vowel almost any letter can come next. So the probability is spread out over many letters. After skr, only a vowel can come next. So most of the probability goes to a few vowels, and the distribution is sharply peaked.", "source": "Predicted (Lectures 17–18) 22"}, {"number": 23, "question": "Why is Atlantic an English word but tlantic impossible?", "answer": "Atlantic is an English word, but tlantic is impossible. This is because in Atlantic, the t and l are on opposite sides of a syllable break (At-lan-tic), so each syllable follows the rules. In tlantic, tl would have to start a syllable. English does not allow tl at the start of a syllable, so tlantic is impossible.", "source": "Predicted (Lectures 17–18) 23"}, {"number": 24, "question": "Could ngop be an English word? Could flim?", "answer": "Ngop could not be an English word. This is because the sound ng can end a syllable, as in ring, but it can never start one.\n\nFlim could be an English word. This is because fl is an allowed onset (the consonants before the vowel), as in flat, and im is an allowed ending.", "source": "Predicted (Lectures 17–18) 24"}, {"number": 25, "question": "Why does a GPT trained only to guess the next letter end up knowing English syllable structure?", "answer": "A GPT trained only to guess the next letter ends up knowing English syllable structure because the patterns of English syllables determine which letters can come next. This is because its guesses can only get better by matching those patterns. So as it learns, its probability distributions take on the shape of those patterns. They are flat after a vowel and sharply peaked after a start such as skr.", "source": "Predicted (Lectures 17–18) 25"}, {"number": 26, "question": "Which letter cannot come next after sp_ at the start of a word: l, r, n or a?", "answer": "N cannot come next after sp at the start of a word. This is because spn is not an allowed English onset (the consonants before the vowel). After sp, only l, r or a vowel can come next, as in split, spring and spa.", "source": "Predicted (Lectures 17–18) 26"}, {"number": 27, "question": "Which letter cannot come next after k_ at the start of a word: a, n or t?", "answer": "T cannot come next after k at the start of a word. This is because kt cannot start an English syllable. After k, a vowel or n can come next, as in knee.", "source": "Predicted (Lectures 17–18) 27"}, {"number": 28, "question": "What can come next after b_ or f_ at the start of a word, and what cannot?", "answer": "After b or f at the start of a word, only r, l or a vowel can come next, as in bring, black, frog and flat. N cannot come next. This is because bn and fn cannot start an English syllable.", "source": "Predicted (Lectures 17–18) 28"}, {"number": 29, "question": "What can come next after sh_ at the start of a word?", "answer": "After sh at the start of a word, only a vowel or r can come next, as in ship and shrimp. This is because shr is the only consonant cluster that English allows starting with sh.", "source": "Predicted (Lectures 17–18) 29"}, {"number": 30, "question": "What can come next after skr_?", "answer": "After skr, only a vowel can come next, as in scream and scrap (where the skr sound is spelled scr). This is because skr already fills the whole onset (the consonants before the vowel). So no other consonant can be added before the vowel.", "source": "Predicted (Lectures 17–18) 30"}, {"number": 31, "question": "Why are lfat, hepl and lapm impossible when flat, help and lamp are words?", "answer": "Lfat, hepl and lapm are impossible because the order of a cluster is a mirror image around the vowel. In flat and help, the l sits right next to the vowel. In lamp, the m sits right next to the vowel. Each impossible version puts the wrong consonant next to the vowel. So it breaks the mirror order, and it cannot be an English word.", "source": "Predicted (Lectures 17–18) 31"}, {"number": 32, "question": "Is ship a consonant, vowel, consonant word even though it has four letters?", "answer": "Yes, ship is a consonant, vowel, consonant word even though it has four letters. This is because the pattern is about sounds, not letters, and sh is one sound. So ship is the consonant sh, the vowel i and the consonant p.", "source": "Predicted (Lectures 17–18) 32"}, {"number": 33, "question": "What would happen if the critic LLM were removed?", "answer": "If the critic LLM were removed, the draft would go straight from writing to the final answer without being checked. This is because the critic is the LLM that checks the draft. So more made-up statements would reach the user. The critic loop is what greatly reduced hallucination, so without it that reduction would be lost.", "source": "Predicted (Lectures 17–18) 33"}, {"number": 34, "question": "What is the difference between Software 2.0 and Software 3.0?", "answer": "The difference between Software 2.0 and Software 3.0 is how the program gets built.\n\nIn Software 2.0, a neural network is trained on input and output data, so the program is the network's weights.\n\nIn Software 3.0, an agentic system builds and runs the program from plain English instructions. Building a program this way is called vibe coding.", "source": "Predicted (Lectures 17–18) 34"}]}, {"id": "new", "title": "Lecture 19 · new slides · 27 predicted questions", "about": "Written from Lecture 19 pages 9 to 19 in the way he asks questions. These are predictions, not confirmed exam questions.", "prefix": "Predicted (Lecture 19)", "items": [{"number": 1, "question": "How does an LLM learn from the sentence \"The chef cracks the ?\"", "answer": "An LLM learns from this sentence by guessing the hidden last word and then changing its weights a little.\n\nThis is because each word before the gap gives a clue about the hidden word. So the model bets the most on \"egg,\" less on \"nut\" and the least on \"code.\" When the true word is revealed, the weights are nudged. So the right word gets a bigger bet next time.", "source": "Predicted (Lecture 19) 1"}, {"number": 2, "question": "Why does the model give \"egg,\" \"nut\" and \"code\" different bets instead of one answer?", "answer": "The model gives three different bets because it does not know the hidden word. All three words could follow \"The chef cracks the.\" The words before the gap make \"egg\" the most likely. So \"egg\" gets the largest bet, \"nut\" gets a smaller bet and \"code\" gets the smallest bet.", "source": "Predicted (Lecture 19) 2"}, {"number": 3, "question": "What does learning change in an LLM, and in which direction?", "answer": "Learning changes the weights. Each weight is nudged, which means it changes a little. The weights change in the direction that gives the right word a bigger bet the next time.", "source": "Predicted (Lecture 19) 3"}, {"number": 4, "question": "Why is text easier for an LLM to read than speech or an image?", "answer": "Text is easier because it is already a row of pieces. Each piece, such as \"Now,\" \"crack,\" \"the\" or \"egg,\" can become one vector.\n\nSpeech is air pressure changing in time, and an image is a grid of light. Neither one contains words or separate pieces. So both have to be converted into rows of vectors first.", "source": "Predicted (Lecture 19) 4"}, {"number": 5, "question": "How is speech turned into a row of vectors?", "answer": "Speech is turned into a row of vectors by slicing it in time. First, the sound is cut into short slices called frames, each about 20 milliseconds long. Then the slices go through a speech encoder, which is a neural network trained on a large amount of audio. One vector comes out for each slice, and the vectors stay in time order.", "source": "Predicted (Lecture 19) 5"}, {"number": 6, "question": "Why does one second of speech become 50 vectors?", "answer": "One second of speech becomes 50 vectors because each slice gives one vector. Each slice is about 20 milliseconds long, and 50 slices of that length fill one second. So one second gives 50 vectors.", "source": "Predicted (Lecture 19) 6"}, {"number": 7, "question": "How is an image turned into a row of vectors?", "answer": "An image is turned into a row of vectors by cutting it into patches. First, a grid cuts the image into small squares called patches. Then the patches are laid out in a row in reading order, so the image becomes a sequence. Last, a vision encoder gives one vector for each patch.", "source": "Predicted (Lecture 19) 7"}, {"number": 8, "question": "The egg example gives 16 vectors. Why does one image give hundreds of vectors in real systems?", "answer": "One image gives hundreds of vectors in real systems because real systems use much smaller patches. Their patches are only 14 to 16 pixels. Smaller patches mean more patches for the same image. Each patch gives one vector, so there are hundreds of vectors.", "source": "Predicted (Lecture 19) 8"}, {"number": 9, "question": "What is the similarity between converting speech and converting an image, and what is the difference?", "answer": "The similarity is that both are cut into small pieces, the pieces are kept in order, and an encoder gives one vector for each piece.\n\nThe difference is what is cut. Speech is cut in time into frames of about 20 milliseconds. An image is cut in space into square patches, which are then placed in reading order.", "source": "Predicted (Lecture 19) 9"}, {"number": 10, "question": "What is a cross-modal dependency? Give an example.", "answer": "A cross-modal dependency is a link between two different kinds of signal, in which a piece from one sense helps predict a piece from another sense.\n\nFor example, in \"Now crack the ?\", an image patch that contains an egg helps the model guess the hidden word. The sound of cracking helps too.", "source": "Predicted (Lecture 19) 10"}, {"number": 11, "question": "When image patches and speech frames are added to the row, what stays the same and what changes?", "answer": "The game stays the same. The model still guesses the hidden piece from the pieces it can read, and the words before the gap still give clues.\n\nWhat changes is where some of the clues come from. Some clues now come from image patches and speech frames.", "source": "Predicted (Lecture 19) 11"}, {"number": 12, "question": "In the spectrogram of \"three cute puppies,\" what do left to right, height and darkness mean?", "answer": "Left to right is time, so \"three\" comes first and \"puppies\" comes last. Height is frequency, so higher up means a higher frequency. Darkness is energy, so a darker area means more energy. Each thin column is one frame.", "source": "Predicted (Lecture 19) 12"}, {"number": 13, "question": "Why are the image, the spectrogram and the words called three views of one event?", "answer": "They are called three views of one event because all three describe the same thing, which is three cute puppies. The image gives it as patches, the speech gives it as frames, and the text gives it as words. In training, all three go into one row.", "source": "Predicted (Lecture 19) 13"}, {"number": 14, "question": "How do the model's bets on the next word change when the image and the sound are added to \"three cute\"?", "answer": "With the words alone, the bets are spread out over \"kittens,\" \"puppies\" and \"babies.\" This is because many endings fit after \"three cute.\"\n\nWith the image and the sound, the bet piles up on \"puppies.\" This is because the image contains puppies, and the sound contains the spoken word \"puppies.\"", "source": "Predicted (Lecture 19) 14"}, {"number": 15, "question": "The model bet 0.85 on \"puppies,\" and the true word is \"puppies.\" Is the nudge to the weights large or small? Why?", "answer": "The nudge to the weights is small. This is because the model is graded on how much it bet on the true word. It bet 0.85, which is a lot, so the error is small. A small error moves the weights only a little.", "source": "Predicted (Lecture 19) 15"}, {"number": 16, "question": "What would happen to the nudge if the model had bet only a little on \"puppies\"?", "answer": "The nudge would be larger. This is because a small bet on the true word is a large error. A larger error moves the weights more, so that the true word gets a bigger bet next time.", "source": "Predicted (Lecture 19) 16"}, {"number": 17, "question": "Name the three clues that help the model predict a hidden sound frame, and say what each one gives.", "answer": "The first clue is the frames already heard. The voice and the formants change smoothly, so the last few frames say a lot about the next one.\n\nThe second clue is the words. They say which sound should come next, which here is the vowel in \"pup.\"\n\nThe third clue is the image. It contains puppies, so it backs up the words, but it is a weaker clue here.", "source": "Predicted (Lecture 19) 17"}, {"number": 18, "question": "What is the error when the model guesses a sound frame?", "answer": "The error is how far the guess is from the true frame. A frame is a column of numbers, and each number is how much energy there is in one frequency band. The error is how far apart each guessed number is from the matching true number. That error nudges the weights.", "source": "Predicted (Lecture 19) 18"}, {"number": 19, "question": "In training example 3, why is the colour the biggest error?", "answer": "The colour is the biggest error because no clue gave the colour of the third puppy. The model guessed a puppy ear in the average colour of the first two puppies. The true puppy is dark. Nothing in the words, the sound or the patches already drawn said the third puppy would be dark.", "source": "Predicted (Lecture 19) 19"}, {"number": 20, "question": "What do the words \"three\" and \"puppies\" tell the model about the hidden image patch?", "answer": "\"Three\" tells the model that a third puppy must appear, because only two puppies have been drawn so far. \"Puppies\" tells the model to expect dog ears. So the model guesses a puppy ear for the hidden patch.", "source": "Predicted (Lecture 19) 20"}, {"number": 21, "question": "Are all systems trained to predict image patches?", "answer": "No. Only systems that also produce images are trained to predict image patches. Systems that only read images usually skip this step. This is because predicting a patch is like teaching the model to draw what it was told.", "source": "Predicted (Lecture 19) 21"}, {"number": 22, "question": "What is the difference between a clue from the same sense as the hidden piece and a clue from another sense?", "answer": "A clue from the same sense mostly says how the signal continues. Grammar does this for a hidden word, smooth formants do it for a hidden frame, and fur and background do it for a hidden patch.\n\nClues from the other senses mostly say what the thing is. Here they say puppies, three of them.", "source": "Predicted (Lecture 19) 22"}, {"number": 23, "question": "For a hidden sound frame, which clue comes from the same sense, and what does it tell the model?", "answer": "The clue from the same sense is that the voice and the formants carry on from the frames already heard. It tells the model how the sound continues. The words and the image are the other senses, and they say which word is being said.", "source": "Predicted (Lecture 19) 23"}, {"number": 24, "question": "Why does training on words, sound and images together help?", "answer": "Training on all three senses together helps because each sense fills gaps that the others leave. A clue from the same sense says how the signal continues. Clues from the other senses say what the thing is. So with all three senses, the model has both kinds of clue for every hidden piece.", "source": "Predicted (Lecture 19) 24"}, {"number": 25, "question": "How does the model talk back?", "answer": "The model talks back by predicting codes for sound. First, sound is compressed into discrete codes, and each code works like a new word in the vocabulary. Then the model predicts the next code exactly as it predicts the next word. Last, a decoder turns the codes back into a sound wave.", "source": "Predicted (Lecture 19) 25"}, {"number": 26, "question": "What three things are new when an LLM is trained on words, sounds and images?", "answer": "The first new thing is a shared currency, in which everything becomes vectors in one row. The second is data where the senses appear together. The third is a schedule that protects what was already learned.", "source": "Predicted (Lecture 19) 26"}, {"number": 27, "question": "What stays the same when the signal holds words, sounds and images?", "answer": "The learning rule stays the same. The model still finds the dependencies in the signal by guessing a hidden piece and nudging its weights. The signal has only become wider.", "source": "Predicted (Lecture 19) 27"}]}]}};
